window.Guide = window.Guide || {};
Guide.manifest = {"generated":"2026-10-13T18:31:56.000Z","title":"Follow the Question","subtitle":"A dial-and-defend field guide to GenAI and AI engineering","version":"1.0.0","regions":[{"id":"foundations","label":"Foundations","blurb":"How models behave, how you call them, and why latency and caching decide what is affordable.","worlds":["w00","w01","w02"]},{"id":"knowledge","label":"Knowledge","blurb":"Get the right content in front of the model: ingestion, chunking, retrieval, guardrails and access control.","worlds":["w03","w04","w05","w06","w07"]},{"id":"agents","label":"Agents and protocols","blurb":"Tools, MCP, A2A, agent patterns and the Microsoft stack that runs them.","worlds":["w08","w09","w10","w11","w12"]},{"id":"senses","label":"Senses and craft","blurb":"Multimodal inputs, evaluation and observability: prove it works and see why it breaks.","worlds":["w13","w14","w15"]},{"id":"operate","label":"Operate and govern","blurb":"Cost, reliability, oversight and the field notes that round out a senior answer.","worlds":["w16","w17","w18"]},{"id":"finale","label":"Finale","blurb":"Mixed boss rounds that combine every region.","worlds":["w19"]}],"worlds":[{"id":"w00","order":0,"region":"foundations","title":"Orientation","short":"Orientation","tagline":"A question is typed into a box. This is where the journey, the method and the map begin.","story":"A question is typed into a box and starts a journey. It will be counted, cached, matched with knowledge, checked, routed through tools and agents, and judged on the way out. At every stop something breaks or forces a choice, and the best answer depends on dials that nobody has told you yet.","oneLiner":"Learn how the guide plays, practise Dial-and-Defend on a gentle board, and read a dated map of what changed in 2025 and 2026 before you quote a spec.","minutes":85,"prereqs":[],"levels":[{"id":"w00-l1","order":1,"title":"A question enters the box","kind":"concept","minutes":10,"quizCount":2,"hasDefend":false,"brief":"A user types one question into a box. Before it becomes an answer it will be counted, cached, matched with knowledge, checked and routed. Find the stop where each kind of failure belongs."},{"id":"w00-l2","order":2,"title":"How this guide plays","kind":"concept","minutes":15,"quizCount":2,"hasDefend":false,"brief":"You have an hour with a group, or twenty minutes alone. Learn the loop each level follows, where your progress lives and which study path fits your time and your gaps."},{"id":"w00-l3","order":3,"title":"Dial and defend in five moves","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"An interviewer asks how to make an assistant answer questions about information the model was never trained on. Notice what a strong answer asks before it names a technology, and practise the five moves on a gentle first board."},{"id":"w00-l4","order":4,"title":"Freshness map A: models, APIs and caching","kind":"concept","minutes":15,"quizCount":3,"hasDefend":false,"brief":"Half of what you read about LLM APIs is out of date, and some of it breaks code. Use this dated map, checked on 2026-10-13, to test a fact before you say it in an answer."},{"id":"w00-l5","order":5,"title":"Freshness map B: protocols, platforms and policy","kind":"concept","minutes":15,"quizCount":3,"hasDefend":false,"brief":"Protocol revisions, agent platforms and regulations all moved in 2025 and 2026, and some pages still teach the old shape. Use this map, checked on 2026-10-13, to label what is GA, what is preview and what has a date on it."},{"id":"w00-l6","order":6,"title":"Boss warm-up: draft the replies","kind":"boss","minutes":12,"quizCount":3,"hasDefend":true,"brief":"A team wants an assistant that drafts replies to customer emails. They have not said how many, how risky or how fast. Practise all five moves in three minutes, aloud."}],"topics":[{"id":"w00-t01","order":1,"group":"Start here","title":"How this guide works","summary":"The guide is a set of standalone topic pages you can open in any order, plus an optional journey of practice problems, labs, flashcards and a progress file you can export.","useIf":"You want to revise one subject fast, follow the whole journey, or run a group session.","avoidIf":"You expect a linear course. Topic pages assume you can jump in and use the related links for depth.","minutes":6,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w00-t02","order":2,"group":"Start here","title":"The GenAI system map","summary":"A GenAI product is a stack of decisions, from the model call to knowledge, tools, agents, proof and operations. Each chapter owns some of those decisions.","useIf":"You need to place a problem on the stack before you pick a technology.","avoidIf":"You already know which layer is failing and need the details of that layer.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w00-t03","order":3,"group":"Answering well","title":"The Dial-and-Defend answer method","summary":"Five moves that turn a design question into a defensible answer: clarify the dials, list options, pick and flip, name failure modes with detection, then state metrics and rollout.","useIf":"You face an open design question and need a structure that shows judgement under time pressure.","avoidIf":"The question is a factual lookup with one right answer, such as a parameter name.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w00-t04","order":4,"group":"Answering well","title":"Reading and answering scenario questions","summary":"A scenario card gives a few fixed constraints and hides the rest. You choose an option, then check its verdict, reason and trade-off against the constraints.","useIf":"You practise with scenario cards and want to learn from the verdicts, not only collect a score.","avoidIf":"You want a single memorised answer per card. Verdicts change when the dials change.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w00-t05","order":5,"group":"Freshness","title":"What changed in 2025 to 2026","summary":"A dated map of the API, protocol and platform changes that break code or old advice, with GA, Preview, Deprecated or Retired status checked on 2026-10-13.","useIf":"You read an older tutorial, answer an interview question about a platform, or plan an upgrade.","avoidIf":"You need today's price or limit: confirm it in the live documentation, because this map is dated.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3}],"quizCount":31,"flashcardCount":36,"refCount":38,"topicCount":5,"scenarioCount":11,"file":"content/w00.js"},{"id":"w01","order":1,"region":"foundations","title":"LLM Controls and APIs","short":"Controls and APIs","tagline":"Tokens, knobs and APIs: what you can control, and what the model quietly rejects.","story":"The question reaches the model. Before it answers, the request is cut into tokens, fitted into a window and shaped by controls that differ by vendor and by model family. Pick wrongly and you get half an answer, a 400 on a parameter that used to work, a bill that jumps at a hidden threshold or state you cannot delete.","oneLiner":"Learn the dials on the model itself, then choose the API, state model and knowledge strategy that survive production.","minutes":120,"prereqs":["w00"],"levels":[{"id":"w01-l1","order":1,"title":"Count the budget before you spend it","kind":"concept","minutes":15,"quizCount":3,"hasDefend":false,"brief":"A request fails on length, or worse, returns half an answer. Before you touch a sampling knob, work out what the token budget is made of and why the same text costs different amounts on different vendors."},{"id":"w01-l2","order":2,"title":"Turn the right knob","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Output is too random, too repetitive or too long, and someone says \"set temperature to 0\". Pick the control that acts on the actual failure, then check that your model and API still accept it."},{"id":"w01-l3","order":3,"title":"Dial the thinking, then pick the model","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"A harder task gets a better answer when the model thinks longer, and you pay for that thinking in latency and output tokens. Decide how much to think, with which model, and whether a router or your own cascade should choose per request."},{"id":"w01-l4","order":4,"title":"Make the output parse every time","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"A downstream parser breaks on one malformed response in a thousand. Decide how much structure to demand from the model, and whether the schema belongs on the answer or on a tool call."},{"id":"w01-l5","order":5,"title":"Decide who owns the conversation","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"A new assistant needs conversation memory, tools and a retention policy that legal can sign. The vendors disagree on who holds the state, so decide who owns it before you write the first request."},{"id":"w01-l6","order":6,"title":"Give the model knowledge it was never trained on","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"The model must answer from information it was never trained on. You can paste it into the prompt, retrieve it per question, preload and cache it, or train it in. Decide with the corpus size, the change rate and the permission model on the table."},{"id":"w01-l7","order":7,"title":"Boss: choose the API and model strategy","kind":"boss","minutes":20,"quizCount":4,"hasDefend":true,"brief":"A team is about to build a new assistant and asks you to pick the API and the model strategy. The dials are not given. Ask for them, offer options and defend a choice."}],"topics":[{"id":"w01-t01","order":1,"group":"Model basics","title":"Tokens and tokenization","summary":"Models read and bill in tokens, which are pieces of text produced by a tokenizer. Counts differ by model family, language, content type and tool definitions.","useIf":"You budget cost, context or latency, migrate between model families, or debug a prompt that is longer than it looks.","avoidIf":"You only need a rough idea and the margin of error does not matter. Even then, never reuse a count from another model family.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t02","order":2,"group":"Model basics","title":"Context windows and output limits","summary":"The context window is one shared budget for input, reasoning and output. A separate cap limits output, and each API names its cap differently.","useIf":"You size prompts, set a max token parameter, or hit truncation, empty answers or 400 errors.","avoidIf":"You think a bigger advertised window means the model uses all of it equally well. See the long-context topic for accuracy.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t03","order":3,"group":"Model basics","title":"Reasoning models and reasoning effort","summary":"Reasoning models spend hidden thinking tokens before they answer. An effort setting trades quality against latency and cost, and some sampling parameters are rejected.","useIf":"You use a reasoning model, tune effort, or see 400 errors after switching models.","avoidIf":"The task is simple extraction or classification where a small non-reasoning model passes your evals.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w01-t04","order":4,"group":"Sampling and decoding","title":"Temperature and top_p","summary":"Temperature reshapes the next-token probabilities, and top_p cuts the candidate list to the most probable tokens. Newer reasoning and Claude models reject non-default values.","useIf":"You tune randomness on a non-reasoning model, or debug a 400 about sampling after a model change.","avoidIf":"The model is a reasoning model with effort above `none`, or a recent Claude model. Control behaviour with prompts, schemas and effort instead.","minutes":6,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t05","order":5,"group":"Sampling and decoding","title":"top_k, seed and determinism","summary":"top_k exists on a few APIs only, seed gives best-effort repeatability on OpenAI Chat Completions, and no major API guarantees identical outputs.","useIf":"You need repeatable behaviour for tests, audits or debugging, or you port code that sets top_k or seed.","avoidIf":"You expect bit-for-bit reproducibility from a hosted model. Design tests and audits around variance instead.","minutes":6,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t06","order":6,"group":"Sampling and decoding","title":"Penalties, logit_bias and stop sequences","summary":"Penalties discourage repeated tokens, logit_bias shifts the odds of specific token ids, and stop sequences end generation at a delimiter. Availability differs by API.","useIf":"You fight repetition, must ban or favour specific tokens, or need generation to end at a known delimiter.","avoidIf":"A prompt change, a schema or a stop sequence would solve it. Penalties and bias are blunt and tokenizer specific.","minutes":6,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t07","order":7,"group":"Sampling and decoding","title":"Logprobs and confidence signals","summary":"Logprobs expose the log probability of each generated token and its top alternatives. They are a usable but uncalibrated signal for classification confidence and abstention.","useIf":"You classify with a non-reasoning model and want a threshold to escalate or abstain.","avoidIf":"You treat a high token probability as proof that a fact is true, or your model path drops logprobs.","minutes":6,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w01-t08","order":8,"group":"Structured interaction","title":"Structured outputs vs JSON mode","summary":"JSON mode guarantees valid JSON. Structured outputs with a strict schema guarantee that the JSON matches your schema, within each platform's schema limits.","useIf":"Code parses the model output and a missing field or wrong type causes a failure.","avoidIf":"The output is free text for a human. A schema adds constraints and failure paths you do not need.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t09","order":9,"group":"Structured interaction","title":"Function and tool calling","summary":"The model returns a tool call with JSON arguments, your code runs it, and you send the result back. Strict schemas, tool_choice and loop limits decide how reliable that cycle is.","useIf":"The model must fetch data or take actions, and you need arguments that your code can trust.","avoidIf":"A single structured answer is enough. A schema-constrained output needs no tool loop.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t10","order":10,"group":"API styles","title":"Chat Completions API","summary":"Chat Completions takes an array of role-tagged messages, returns choices, and keeps no state: your application sends the full history on every call.","useIf":"You target many OpenAI-compatible vendors, run non-reasoning models, or want to own conversation state.","avoidIf":"You need reasoning models with tools on recent OpenAI models, built-in tools or server-held state. Use the Responses API.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t11","order":11,"group":"API styles","title":"Responses API","summary":"Responses takes and returns typed Items, can hold state on the server, and adds built-in tools, background runs and encrypted reasoning. OpenAI recommends it for new projects.","useIf":"You build new work on OpenAI or Azure OpenAI, use reasoning models with tools, or want built-in tools and server-held state.","avoidIf":"You must target many OpenAI-compatible vendors with one format, or a retention policy forbids server-held state and you have not designed a stateless path.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t12","order":12,"group":"API styles","title":"Chat Completions vs Responses: choosing and migrating","summary":"Choose the API from four dials: model family, state ownership, portability and retention. Migrating means changing message shapes, reading output Items and deciding where state lives.","useIf":"You pick an API for a new build, plan a migration, or map an Assistants or Azure app to current APIs.","avoidIf":"You treat Responses as a renamed Chat Completions. It changes state, tools, reasoning handling and several parameters.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w01-t13","order":13,"group":"API styles","title":"Streaming and background mode","summary":"Streaming sends tokens as events so users see output early. Background mode runs a long call on the server while you poll. Batch handles bulk offline work.","useIf":"A user waits on a response, a call outlasts an HTTP timeout, or you process large volumes offline.","avoidIf":"You act on partial output. Never execute a tool call or parse JSON before the item is complete.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w01-t14","order":14,"group":"Adapting models","title":"Prompting vs RAG vs long context vs fine-tuning","summary":"Prompting and context carry facts at run time, RAG fetches them per question, long context preloads them, and fine-tuning changes behaviour. Evidence says use fine-tuning for style, not for facts.","useIf":"You decide how a model gets knowledge or a behaviour it does not have.","avoidIf":"You pick a method before measuring corpus size, update rate, permissions, volume and accuracy needs.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w01-t15","order":15,"group":"Adapting models","title":"Fine-tuning methods: SFT, DPO, RFT and LoRA","summary":"SFT learns from correct answers, DPO from preferred and rejected pairs, RFT from a grader, and LoRA is a cheap way to train adapters. Platform availability is the first question.","useIf":"You need a consistent format, tone, tool-use behaviour or a smaller model and you have examples.","avoidIf":"You want to add facts or current information. Evidence favours retrieval for that.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w01-t16","order":16,"group":"Adapting models","title":"Distillation and small models","summary":"Distillation trains a small student model on a large teacher's outputs. Small models cost far less per token, and they win on narrow, high-volume, latency-bound tasks when evals confirm quality.","useIf":"Volume, latency or cost per task rules out the largest model and the task is narrow enough for a small one.","avoidIf":"The task is open-ended, rare and high stakes, or you cannot build an eval set to compare student and teacher.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w01-t17","order":17,"group":"Adapting models","title":"Model routing and cascades","summary":"A router picks a model per request, and a cascade tries a cheap model first and escalates on low confidence or a failed check. Both save cost only if you evaluate them against single-model baselines.","useIf":"Traffic mixes easy and hard requests and one model is either too costly or too weak for all of it.","avoidIf":"Traffic is uniform, volume is low, or you have no eval set. A single model also gives the best prompt-cache reuse.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3}],"quizCount":74,"flashcardCount":87,"refCount":62,"topicCount":17,"scenarioCount":39,"file":"content/w01.js"},{"id":"w02","order":2,"region":"foundations","title":"Latency, KV Cache and Prompt Caching","short":"Latency and caching","tagline":"Why the answer is slow, and which cache makes it fast without making it wrong.","story":"The question has reached the model and it waits: in a queue, in prefill, and in a decode loop that emits one token at a time. Latency and cost both trace back to how the model stores what it has already read. Every cache you add trades speed and money against correctness and isolation, and the quietest failures are the caches that stop hitting.","oneLiner":"Name the bottleneck first, then pick the lever and the cache whose risk your dials can afford.","minutes":125,"prereqs":["w01"],"levels":[{"id":"w02-l1","order":1,"title":"Read the stopwatch","kind":"concept","minutes":15,"quizCount":3,"hasDefend":false,"brief":"A user says the assistant feels slow. Before you touch anything, decide what you are timing: the wait for the first word, the speed of the words after it, or the whole answer. Prompt length, output length and traffic shape are not given yet."},{"id":"w02-l2","order":2,"title":"Keep the GPU busy without stalling users","kind":"problem","minutes":15,"quizCount":3,"hasDefend":false,"brief":"Many users share one model. Long prompts stall short ones, single streams crawl, and the GPU idles between requests. The model size, GPU count, traffic mix and whether you host the model yourself are all open."},{"id":"w02-l3","order":3,"title":"Size the KV cache before it sizes you","kind":"lab","minutes":20,"quizCount":3,"hasDefend":false,"brief":"A model must serve many long conversations on a fixed GPU. The architecture, KV precision, context length and concurrency are all open. Find which dial caps concurrency, and which of your options can still move."},{"id":"w02-l4","order":4,"title":"Rent the prefix: how providers sell caching","kind":"problem","minutes":15,"quizCount":3,"hasDefend":false,"brief":"You call a hosted model with a long, mostly repeated prompt. Vendors cache the prefix differently, charge differently for writes and expire entries on different clocks. The model family, request spacing and retention rules are all open."},{"id":"w02-l5","order":5,"title":"Engineer the hit rate","kind":"lab","minutes":20,"quizCount":3,"hasDefend":false,"brief":"The dashboard says caching is on, yet the bill barely moved. Hit rate depends on prefix stability, request spacing, routing and lifetime, and none of them is fixed. Find what to change first, and how you would notice a silent regression."},{"id":"w02-l6","order":6,"title":"Beyond the prefix: caches that change the answer","kind":"problem","minutes":20,"quizCount":4,"hasDefend":false,"brief":"Some caches skip the model altogether. They save the most and carry the most risk: stale answers, near-miss matches and one user's data surfacing for another. How often questions repeat, who shares the cache and how costly a wrong answer is are all open."},{"id":"w02-l7","order":7,"title":"Boss: make it feel instant","kind":"boss","minutes":25,"quizCount":3,"hasDefend":true,"brief":"An interviewer says: the assistant feels slow and costs too much, so make it feel instant without breaking correctness or isolation between users. Nothing else is given. Build a budget, rank the levers, then defend your plan."}],"topics":[{"id":"w02-t01","order":1,"group":"Latency fundamentals","title":"TTFT, TPOT, throughput and queueing","summary":"Four numbers describe an LLM call: time to first token, time per output token, total latency and throughput. Each has a different driver, so name the one the product is judged on before you fix anything.","useIf":"Someone says the assistant feels slow and you must decide what to measure and which stage to attack.","avoidIf":"You already have per-stage traces with token counts and a metric the product is judged on. Go straight to the lever.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w02-t02","order":2,"group":"Latency fundamentals","title":"Streaming and perceived latency","summary":"Streaming sends tokens to the client as they are generated. Total time does not change, but the first word appears sooner and long calls stop timing out.","useIf":"A person reads the answer as it arrives and the answer is longer than a sentence or two.","avoidIf":"A program consumes the whole answer, or a check must see the full text before anyone may display it.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w02-t03","order":3,"group":"Latency fundamentals","title":"Prefill vs decode","summary":"Prefill reads the whole prompt in parallel and is compute-bound. Decode emits one token per step and is memory-bandwidth-bound. Prompt length drives the first, output length drives the second.","useIf":"You need to decide whether a slow call is a prompt problem or an output problem, and which lever fits.","avoidIf":"You only call a hosted model and the slowness is clearly queueing or rate limiting, not model time.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w02-t04","order":4,"group":"KV cache and serving","title":"The KV cache and how big it gets","summary":"The KV cache stores the keys and values of every token already read so decode never recomputes them. It grows with context length and concurrency and, at long context, caps how many users fit on a GPU.","useIf":"You host a model and must size concurrency, or you must explain why long context makes serving expensive.","avoidIf":"You only call a hosted API. The provider manages the KV cache, and your levers are prompt size, output size and prompt caching.","minutes":10,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w02-t05","order":5,"group":"KV cache and serving","title":"MHA, GQA, MQA and MLA","summary":"Attention variants decide how many key and value heads a model stores. Fewer KV heads, or a compressed latent, shrink the KV cache and the memory traffic of decode, at some quality risk.","useIf":"You compare open models for serving cost, or you must explain why two models of equal size need different GPU memory.","avoidIf":"You call a hosted API and cannot see or change the attention design.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t06","order":6,"group":"KV cache and serving","title":"PagedAttention and fragmentation","summary":"PagedAttention stores the KV cache in fixed-size blocks mapped through a block table, like virtual memory pages. It removes most reserved-but-unused memory and lets requests share blocks.","useIf":"You run your own inference engine and want more concurrent sequences per GPU, or you need to understand how engines share KV.","avoidIf":"You use a hosted API. The provider's engine already does this, and you cannot tune it.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t07","order":7,"group":"KV cache and serving","title":"Continuous batching and chunked prefill","summary":"Continuous batching schedules the GPU one iteration at a time so finished requests leave and new ones join. Chunked prefill splits long prompts so they stop stalling everyone else's streams.","useIf":"You run an inference engine for many users with mixed prompt lengths and you see throughput gaps or ITL spikes.","avoidIf":"You only call a hosted API. Engine scheduling is not yours to tune, and the lever there is separating workloads.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t08","order":8,"group":"KV cache and serving","title":"Server-side prefix caching","summary":"Inference engines can keep the KV blocks of finished requests and reuse them when a new request starts with the same tokens. It is the self-hosted twin of provider prompt caching.","useIf":"You run your own engine and many requests share a long prefix such as a system prompt, tools or a document.","avoidIf":"Prompts are unique, or tenants must not infer each other's prompts and you have not set up isolation.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t09","order":9,"group":"KV cache and serving","title":"Speculative decoding","summary":"A cheap draft proposes several tokens and the large model verifies them in one pass. Accepted tokens come at the price of one step, and the output distribution stays the same.","useIf":"You run your own model, single-stream decode speed matters, and load is low to medium so the GPU is memory-bound with spare compute.","avoidIf":"The GPU is saturated by large batches, or the draft agrees with the target too rarely to pay for itself.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t10","order":10,"group":"KV cache and serving","title":"Quantization: weights and KV cache","summary":"Quantization stores numbers in fewer bits. Quantizing weights shrinks the model and speeds memory-bound decode. Quantizing the KV cache lets more sequences fit. Both trade quality risk for capacity.","useIf":"You host a model and weights or KV memory limit capacity, and you can run an eval before and after.","avoidIf":"You use a hosted API, or you cannot test quality on your own tasks, especially at long context.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t11","order":11,"group":"Prompt caching","title":"Prompt caching: what makes a hit","summary":"A provider prompt cache reuses the stored KV state of a repeated prefix. It changes cost and time to first token, never the answer. A hit needs four things at once: enough tokens, an identical prefix, the right machine and a request inside the lifetime.","useIf":"Requests share a long, stable prefix such as a system prompt, tool list, reference text or growing chat history.","avoidIf":"Prompts are short or unique, or reuse is so sparse that writes cost more than reads save.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w02-t12","order":12,"group":"Prompt caching","title":"OpenAI and Azure OpenAI prompt caching","summary":"OpenAI and Azure OpenAI cache prefixes automatically. GPT-5.6 and later add explicit breakpoints, a write charge, a 30 minute lifetime and prewarming. Older models keep the implicit, free-to-write behaviour.","useIf":"You call OpenAI or Azure OpenAI with a long, stable prefix and need to choose a mode, a retention setting and where to put breakpoints.","avoidIf":"You use another provider (see the Anthropic topic) or you run your own engine (see server-side prefix caching).","minutes":10,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t13","order":13,"group":"Prompt caching","title":"Anthropic cache_control","summary":"Anthropic caches only what you mark. Automatic caching adds one top-level marker that follows the conversation. Explicit caching places up to four breakpoints. Entries last 5 minutes or 1 hour, and writes cost more than reads.","useIf":"You call Claude models directly or through Bedrock or Foundry and want to control exactly which prefix is cached and for how long.","avoidIf":"Reuse is sparse, so writes would never be read, or the prefix is under the model's minimum size.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t14","order":14,"group":"Prompt caching","title":"Designing prompts for cache hits","summary":"Hit rate is something you engineer. Put content in order of how rarely it changes, keep tools and settings frozen, shard hot prefixes across keys and alert when the cached share drops.","useIf":"You pay for a long prefix on every call and the dashboard shows few cached tokens, or you are designing a new prompt layout.","avoidIf":"Reuse is too sparse for any cache to hit, in which case the fix is to turn caching off, not to reshape the prompt.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w02-t15","order":15,"group":"Other caches and budgets","title":"Semantic cache","summary":"A semantic cache embeds the prompt and returns a stored answer when a similar earlier prompt is close enough. It skips the whole model call, and it changes what the user sees, so it can be wrong, stale or leak across users.","useIf":"Many users ask paraphrases of the same questions, the answer is the same for everyone, and a slightly stale answer is acceptable.","avoidIf":"Answers depend on who asks, on live data or on high-stakes accuracy, or paraphrases rarely repeat.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w02-t16","order":16,"group":"Other caches and budgets","title":"Response and embedding caches","summary":"An exact-match response cache returns a stored answer for an identical request. An embedding cache reuses vectors for unchanged text. Both save calls, and both are only as safe as their keys and invalidation rules.","useIf":"The same exact inputs repeat, as in retries, re-runs, re-ingestion of unchanged documents or fixed tool and resource lists.","avoidIf":"Inputs rarely repeat exactly, answers must vary or stay fresh, or you cannot build a key that carries scope and versions.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w02-t17","order":17,"group":"Other caches and budgets","title":"End-to-end latency budgets","summary":"A latency budget splits a target such as time to first token into stage allowances. Run independent stages in parallel, watch the tail not the mean, and attack the stage that dominates before touching the others.","useIf":"A request crosses several stages (auth, rewrite, retrieval, guards, model, output checks) and you must hit a latency target.","avoidIf":"The system is a single model call with no other stages. Use the TTFT and TPOT topics directly.","minutes":10,"difficulty":"core","scenarioCount":2,"quizCount":3}],"quizCount":73,"flashcardCount":72,"refCount":50,"topicCount":17,"scenarioCount":34,"file":"content/w02.js"},{"id":"w03","order":3,"region":"knowledge","title":"Data Ingestion","short":"Ingest the data","tagline":"The answer is not in the system yet. Get it in, keep it true, and know when it is wrong.","story":"The question has crossed the model and the cache, and it needs knowledge the system does not hold yet. Files sit in storage, rows change in a database, pages live in a library with permissions, and some of it is scanned paper. Ingestion decides what the assistant can ever know, how stale it is, and whether a deleted or restricted document keeps answering. This world is the choice of pipeline and the discipline of keeping the index equal to the source.","oneLiner":"Choose how content gets in, parse it faithfully, keep it fresh, repeatable and deletable, and gate what enters the index.","minutes":85,"prereqs":["w02"],"levels":[{"id":"w03-l1","order":1,"title":"Pick the pipe","kind":"problem","minutes":15,"quizCount":3,"hasDefend":false,"brief":"Files, rows and pages must become searchable chunks. Nobody has told you the freshness target, the source mix or who carries the pager. Choose how content gets in, and say what would flip your choice."},{"id":"w03-l2","order":2,"title":"Parse it right or pay for it later","kind":"problem","minutes":15,"quizCount":3,"hasDefend":false,"brief":"Half of the corpus is clean exports, the rest is scans with merged-cell tables, forms and charts. One parser for everything is tempting. Pick by document type, volume and where the text may travel."},{"id":"w03-l3","order":3,"title":"Changed, repeated, deleted","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"Documents change, events arrive twice, sources delete files without telling anyone, and the embedding model will change next year. Make the index tell the truth about the source, and say how you would prove it."},{"id":"w03-l4","order":4,"title":"Poison, pressure and permissions","kind":"problem","minutes":15,"quizCount":3,"hasDefend":false,"brief":"One corrupt PDF blocks the queue, the embedding API starts returning 429, and compliance asks whether a national id number can reach the index and who may read it. Decide what the pipeline does at each gate."},{"id":"w03-l5","order":5,"title":"Boss: the mixed, changing corpus","kind":"boss","minutes":18,"quizCount":4,"hasDefend":true,"brief":"An interviewer describes four kinds of source, content that changes all day and permissions that differ per document. No numbers are given. Design the ingestion layer and defend it."}],"topics":[{"id":"w03-t01","order":1,"group":"Architecture","title":"Ingestion architectures: indexer, push, event-driven, batch","summary":"Four ways to get content into a search index: a managed indexer pulls on a schedule, your code pushes documents, an event pipeline reacts to changes, or a batch job rebuilds in bulk.","useIf":"You must pick how content reaches the index and can state the freshness target, the source type and who will operate the pipeline.","avoidIf":"You treat the choice as permanent: most real systems mix a pull path for bulk content with a push path for hot content.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w03-t02","order":2,"group":"Architecture","title":"Source connectors and access patterns","summary":"A connector choice is three questions: does an indexer exist and in what release state, how does the source say something changed or was deleted, and how do you authenticate without being throttled.","useIf":"You are choosing how to read SharePoint, Blob or ADLS Gen2, OneLake, SQL, Cosmos DB or the web into an index.","avoidIf":"You pick a connector by popularity: preview status, delete visibility and throttling decide whether it survives production.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w03-t03","order":3,"group":"Parsing","title":"Text extraction, OCR and layout analysis","summary":"Three ways to turn a file into text: read the embedded text layer, run OCR on page images, or run layout analysis that also recovers reading order, headings, tables and figures.","useIf":"Your files include scans, multi-column pages, tables or forms and you must decide how much parsing each document type deserves.","avoidIf":"Every file is clean born-digital text: a heavy parser adds cost and a new failure surface for no gain.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w03-t04","order":4,"group":"Parsing","title":"Vision LLMs and Content Understanding for parsing","summary":"A vision model reads a page image directly and can explain charts and messy layouts that OCR flattens. Azure Content Understanding wraps analysis in schema-defined fields with confidence and grounding.","useIf":"Pages carry meaning in charts, diagrams or irregular layouts, or you need typed fields with confidence and grounding rather than free text.","avoidIf":"Documents are clean text or ordinary tables and you need cheap, repeatable output: layout analysis wins on cost and determinism.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w03-t05","order":5,"group":"Parsing","title":"Tables, figures and forms","summary":"Tables, figures and forms hold facts that plain text parsing scrambles. You choose a representation at ingest: a table block, row sentences, a structured store, a figure caption or typed form fields.","useIf":"Answers depend on cells, charts or checkboxes and you must decide how each is stored and retrieved.","avoidIf":"Tables are tiny decoration: indexing them as ordinary text is fine.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w03-t06","order":6,"group":"Keeping it fresh","title":"Incremental ingestion and change detection","summary":"Incremental ingestion processes only what changed since the last run, using a timestamp, a change log or a content hash, and falls back to a full rebuild when the pipeline itself changes.","useIf":"The corpus is large, changes slowly relative to its size and you want cost and run time to follow the changes, not the corpus.","avoidIf":"The corpus is small or the source gives no reliable change signal: a scheduled full reload is simpler and safer.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w03-t07","order":7,"group":"Keeping it fresh","title":"CDC and event-driven pipelines","summary":"Change data capture and storage events push changes to you in seconds. Delivery is at least once and unordered, so the pipeline must treat events as hints and write idempotently.","useIf":"Freshness must be seconds, the source emits changes (change feed, database log, storage events) and you can run a queue and workers.","avoidIf":"Hourly freshness is enough and a supported indexer exists: events add operational burden with no business gain.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w03-t08","order":8,"group":"Keeping it fresh","title":"Idempotency, dedupe and hashing","summary":"Idempotent ingestion gives the same index state however many times a change is delivered. It rests on stable ids, normalised content hashes and a deliberate rule for duplicates.","useIf":"Events, retries or replays can deliver the same document twice, or the same text exists in many copies.","avoidIf":"You build one-off loads that never rerun: key design still helps, but the dedupe machinery is overkill.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w03-t09","order":9,"group":"Keeping it fresh","title":"Deletes, versioning and re-embedding","summary":"Deletes need a visible tombstone, versions need a rule for what the index keeps, and re-embedding needs a second index and an alias, because vectors from different models cannot be mixed.","useIf":"Content is removed or superseded, a legal deletion deadline exists, or you will change embedding models during the life of the index.","avoidIf":"The corpus is a frozen archive that is never edited or re-embedded: a simple one-time build is enough.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w03-t10","order":10,"group":"Quality and failure","title":"Failure handling: dead letters, backpressure and replay","summary":"Ingestion fails in three ways: transient errors you retry, poison items you quarantine, and overload you absorb with backpressure. A dead-letter queue and idempotent replay make all three recoverable.","useIf":"Your pipeline calls rate-limited services (embeddings, parsers, source APIs) or processes untrusted files at volume.","avoidIf":"A tiny batch job runs under supervision: log failures and rerun it.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w03-t11","order":11,"group":"Quality and failure","title":"Quality gates: PII, ACL capture and metadata","summary":"Quality gates sit between parsing and indexing. They stop bad text, sensitive data and chunks with no permissions from entering the index, and they stamp each chunk with the metadata that retrieval and debugging need.","useIf":"The index holds personal data, per-document permissions or content you must trace back to a source, version and parser.","avoidIf":"The corpus is public, flat and low risk: keep the gates light and measure drift instead.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3}],"quizCount":49,"flashcardCount":50,"refCount":76,"topicCount":11,"scenarioCount":22,"file":"content/w03.js"},{"id":"w04","order":4,"region":"knowledge","title":"Chunking, Embeddings and Indexes","short":"Chunk and embed","tagline":"The content is in, but in pieces. Cut it, embed it and index it so the right piece can be found.","story":"Parsed text is still one long stream, and a model cannot read a thousand pages for each question. The system must cut the text into retrievable pieces, turn each piece into a vector, and store the vectors where a filtered nearest-neighbour search can find them in milliseconds. Every choice here is a trade: a chunk too small loses its meaning, a vector too large exhausts memory, and a filter too selective can return nothing. This world is the choice of chunk, model, compression and index, and the discipline of measuring each against your own questions.","oneLiner":"Choose how to cut, embed, compress and index content, and prove each choice on your own questions.","minutes":90,"prereqs":["w03"],"levels":[{"id":"w04-l1","order":1,"title":"Cut it right","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"The text is parsed and in one piece. Policies with headings, tickets, contracts and wiki prose all need cutting into retrievable chunks, and nobody has told you the question types or the ingest budget. Choose a cutting rule and say how you would prove it."},{"id":"w04-l2","order":2,"title":"Put the context back","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"A chunk that says 'the fee is 2%' no longer says which product, contract or year. Choose how to give small chunks their context back, and decide what to do with tables, code and figures. The ingest budget and the edit rate are not stated."},{"id":"w04-l3","order":3,"title":"Spend vectors wisely","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Twenty million chunks, a memory quota that is already tight, a mix of languages and an embedding model that will be retired within years. Choose the model, the dimensions and the compression, and say how you would prove recall held."},{"id":"w04-l4","order":4,"title":"Index, filter, store","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"The vectors exist. Choose an index family and its knobs, explain why a tenant filter can make a top-10 query return three rows, and pick a store. The vector count, the filter selectivity and the operations model are not stated."},{"id":"w04-l5","order":5,"title":"Boss: one index, five kinds of document","kind":"boss","minutes":20,"quizCount":4,"hasDefend":true,"brief":"An interviewer describes policies, scanned manuals, table-heavy contracts, support chats and source code in one assistant, with lookups, broad questions and tenant filters. No numbers are given. Design the chunking, embedding and index layers and defend them."}],"topics":[{"id":"w04-t01","order":1,"group":"Chunking","title":"Why chunk and what makes a good chunk","summary":"A chunk is the piece of a document that the index stores, embeds and returns. Its size and shape decide what the retriever can match and what the model gets to read.","useIf":"Documents are longer than one idea or longer than the embedding input limit, so you need a retrieval unit smaller than the file.","avoidIf":"Each record is already one short, self-contained answer (an FAQ entry, a product row). Index it whole instead of splitting it.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w04-t02","order":2,"group":"Chunking","title":"Fixed-size chunking with overlap","summary":"Cut the text every N tokens or characters and step back by an overlap so a sentence near a boundary lands in two chunks. It is the cheapest strategy and the baseline for every other one.","useIf":"You need a predictable, cheap baseline, or the text has no headings or paragraphs to split on.","avoidIf":"The documents have headings, tables or code. A blind cut will separate rows from headers and bodies from titles.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w04-t03","order":3,"group":"Chunking","title":"Recursive and sentence-based chunking","summary":"Split on the largest natural boundary that keeps pieces under the limit: paragraph first, then line, then sentence, then space. Sentence-based chunking packs whole sentences, or embeds single sentences and returns a window around them.","useIf":"The text is prose with paragraphs and sentences, and you want cleaner boundaries than a blind cut at the same low cost.","avoidIf":"The text has real structure (headings, tables, code) that separators cannot see, or the language lacks reliable sentence punctuation.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w04-t04","order":4,"group":"Chunking","title":"Semantic chunking","summary":"Embed the sentences, compare neighbours and start a new chunk where similarity drops. Boundaries follow topic shifts instead of length, at the price of an extra embedding pass and less stable chunks.","useIf":"Long text shifts topic without headings, you can afford an ingest-time embedding pass and you have measured a gain over a simple splitter.","avoidIf":"The corpus is huge, changes often or already has structure. Studies have not found consistent gains for the cost.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t05","order":5,"group":"Chunking","title":"Structure-aware chunking","summary":"Parse the document's own structure (headings, sections, tables, layout) and split along it, keeping the section path as metadata. Chunks follow the author's meaning, not a token counter.","useIf":"Documents have headings, tables or layout and answers live inside sections you can name.","avoidIf":"The text is flat, or the parser cannot recover headings reliably, so the structure you split on is wrong.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w04-t06","order":6,"group":"Chunking","title":"Parent-child (small-to-big) retrieval","summary":"Match the query against small child chunks for precision, then return the larger parent section, page or window to the model for context.","useIf":"Small chunks find the answer but the model needs the surrounding section to use it.","avoidIf":"Retrieval must be a single cheap lookup with a tiny prompt, or documents are so short that a single chunk size already works.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w04-t07","order":7,"group":"Chunking","title":"Proposition chunking","summary":"An LLM rewrites each passage into atomic, self-contained facts (propositions) and each one is embedded on its own. Matching gets very precise, at the cost of an LLM pass at ingest and many more vectors.","useIf":"Questions target individual facts about named entities, the corpus is stable and ingest budget allows an LLM pass.","avoidIf":"The corpus is huge or volatile, or the exact original wording must be the evidence and a rewrite is a risk.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t08","order":8,"group":"Chunking","title":"Contextual retrieval","summary":"An LLM writes a short, chunk-specific context from the whole document and the context is prepended to the chunk before embedding and before building the keyword index. Ambiguous chunks become findable.","useIf":"Chunks lose their subject when cut ('revenue grew 3%') and lookups fail on ambiguous passages.","avoidIf":"Documents change constantly or ingest budget is tiny. Cheaper context (title and section path) may be enough.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t09","order":9,"group":"Chunking","title":"Late chunking","summary":"Run the whole document through a long-context embedding model first, then cut the token embeddings into chunks and pool each one. Every chunk vector carries document context with no extra LLM calls.","useIf":"You run a long-context embedding model whose token-level outputs you can access and chunks lean on document context (pronouns, references).","avoidIf":"You only have a hosted embedding API that returns one pooled vector per input, or documents are longer than the model's context.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t10","order":10,"group":"Chunking","title":"Hierarchical summaries (RAPTOR)","summary":"Cluster chunks, summarise each cluster with an LLM, then repeat on the summaries to build a tree. Search all levels so one query can reach a detail or a theme.","useIf":"Questions need whole-document or multi-section understanding, such as themes, arcs or comparisons across a long text.","avoidIf":"Questions are lookups answered by one passage, or the corpus changes often and rebuilding the tree is costly.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t11","order":11,"group":"Chunking","title":"Tables, code and figures","summary":"Tables, code and figures break text splitters. Keep each as a unit, repeat headers and signatures, and turn figures into searchable descriptions linked to the original image.","useIf":"Documents carry tables, code or diagrams and users ask about the values, functions or pictures inside them.","avoidIf":"The corpus is prose only. Do not pay for table, code and figure handling you will never retrieve.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w04-t12","order":12,"group":"Embeddings","title":"Embedding models and how to choose","summary":"The embedding model decides what 'similar' means in your index. Choose it by quality on your own documents and languages, then by dimensions, cost, latency, hosting and lifecycle.","useIf":"You are picking or revisiting the model that turns chunks and queries into vectors.","avoidIf":"You would choose from a public leaderboard rank alone. It is a shortlist, not a decision.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w04-t13","order":13,"group":"Embeddings","title":"Dimensions and Matryoshka embeddings","summary":"Vector size drives storage and speed. Matryoshka-trained models let you keep only the first dimensions of a vector, trading a little recall for a large saving.","useIf":"Vector memory or cost is a constraint and your model was trained for Matryoshka truncation.","avoidIf":"The corpus is small, so the saving is negligible, or the model was not trained for truncation.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w04-t14","order":14,"group":"Embeddings","title":"Embedding quantization and rescoring","summary":"Store each vector component in fewer bits (int8 or one bit), search the compressed index for extra candidates, then rescore them with the original vectors. You get a large memory saving with a small recall cost.","useIf":"Vector memory is the cost driver and you can afford a rescoring step against original vectors.","avoidIf":"The index is small or dimensions are low. Binary quantization on small vectors loses too much.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t15","order":15,"group":"Embeddings","title":"Asymmetric prompts, multilingual and drift","summary":"Many embedding models need different prefixes for queries and documents. Quality varies across languages. Any change to model, version or prefix makes old vectors incomparable, so pin them and plan migrations.","useIf":"You self-host an open embedding model, serve several languages, or must change models without breaking search.","avoidIf":"You cannot version the embedding setup. Unversioned changes cause silent quality loss.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t16","order":16,"group":"Indexes","title":"ANN index families: flat, HNSW, IVF, DiskANN","summary":"Exact search compares the query with every vector. Approximate indexes (HNSW, IVF, DiskANN) skip most of them, trading a little recall for speed, and differ in memory, build cost and scale.","useIf":"You are choosing an index type or diagnosing recall, latency or memory in a vector store.","avoidIf":"The set to search is small after filtering. An exact scan is simpler and always right.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w04-t17","order":17,"group":"Indexes","title":"HNSW parameters","summary":"HNSW has three knobs: m (links per node), efConstruction (build-time effort) and efSearch (query-time effort). They trade recall against memory, build time and latency, and the defaults differ by product.","useIf":"You run an HNSW index and need to tune recall, latency or memory with evidence instead of guessing.","avoidIf":"You have no exact-search baseline. Without it you cannot tell whether a change improved recall.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t18","order":18,"group":"Indexes","title":"Filtered vector search","summary":"Vector search with a metadata filter (tenant, language, date, access) can lose recall or return too few results if the filter is applied after the approximate search. Where and how the filter runs decides the outcome.","useIf":"Queries carry filters: tenants, document types, dates or access groups. Choose the filter strategy deliberately.","avoidIf":"Every query searches the whole index with no filter. Then the index defaults are enough.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w04-t19","order":19,"group":"Indexes","title":"Vector store options compared","summary":"Azure AI Search, Cosmos DB for NoSQL, PostgreSQL, Redis, Qdrant, Pinecone, Elasticsearch and OpenSearch can all hold vectors. The right one depends on where the data lives, filters and hybrid search, scale and who runs it.","useIf":"You are picking where vectors live, or checking whether the store you have still fits its scale and filters.","avoidIf":"You would choose by a vendor benchmark. Compare on your own vectors, filters and operating model.","minutes":10,"difficulty":"core","scenarioCount":3,"quizCount":2}],"quizCount":73,"flashcardCount":82,"refCount":90,"topicCount":19,"scenarioCount":41,"file":"content/w04.js"},{"id":"w05","order":5,"region":"knowledge","title":"Retrieval and RAG Patterns","short":"Retrieve and rank","tagline":"The right chunk is in the index. Will the system find it, rank it first and know when it found nothing?","story":"The content is chunked, embedded and indexed, and the question arrives. The system has to turn a few words into the right three passages out of millions. It can miss an exact identifier, bury the best chunk at rank 31, rewrite the question into something else, or answer confidently from a weak shortlist. This world is the choice of retrieval stack and the discipline of debugging it.","oneLiner":"Choose how to search, fuse, rerank, rewrite, plan and cite, and know which dial flips each choice.","minutes":115,"prereqs":["w04"],"levels":[{"id":"w05-l1","order":1,"title":"Keywords, vectors or both?","kind":"problem","minutes":14,"quizCount":3,"hasDefend":false,"brief":"One search box receives an error code, a product name and a paraphrased policy question in the same hour. Which retriever do you trust first, and what does each one lose?"},{"id":"w05-l2","order":2,"title":"Fuse the lists without tuning a dozen knobs","kind":"lab","minutes":16,"quizCount":4,"hasDefend":false,"brief":"Two ranked lists disagree. One speaks BM25 and one speaks cosine, and their scores sit on different scales. How do you merge them, and when is the zero-tuning default the wrong choice?"},{"id":"w05-l3","order":3,"title":"Rerank the shortlist, set the cutoff, know when to abstain","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"Hybrid search returned fifty plausible chunks and the answer needs three. Who decides the order, where do you cut, and what does the system do when nothing is good enough?"},{"id":"w05-l4","order":4,"title":"Rewrite the question, resize the chunk","kind":"problem","minutes":15,"quizCount":3,"hasDefend":false,"brief":"Users type three words, or five questions in one breath, or a follow-up that only makes sense with the last turn. The index expects something else. Do you change the query, the chunk grain, or both?"},{"id":"w05-l5","order":5,"title":"Past top-k: trees, graphs and planners","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"Some questions have no single answer chunk: the main themes across thousands of reports, or a question with three parts. When does a structure beyond a flat list of chunks pay for its index bill and its latency?"},{"id":"w05-l6","order":6,"title":"Retrieve, stuff or cache? Then cite it and debug it","kind":"problem","minutes":17,"quizCount":4,"hasDefend":false,"brief":"The corpus fits in a context window. Or nearly does. Or it fits for one user and not for another. Retrieval is no longer the only way to put knowledge in a prompt, and whichever you pick, a bad answer still needs a debugging path and every claim needs a source."},{"id":"w05-l7","order":7,"title":"Boss: the identifier and the paraphrase","kind":"boss","minutes":18,"quizCount":3,"hasDefend":true,"brief":"An interviewer describes an assistant whose users type error codes and paraphrased policy questions into the same box. No numbers are given. Design the retrieval stack and defend it."}],"topics":[{"id":"w05-t01","order":1,"group":"Baseline","title":"RAG pipeline anatomy","summary":"Retrieval-augmented generation fetches evidence at question time and hands it to the model. The pipeline has a fixed set of stages, and each one can lose the answer.","useIf":"You are building or reviewing a RAG system and need a map of where answer quality is won or lost.","avoidIf":"The knowledge is small, stable and shared, so a plain long prompt does the job without a retrieval stack (see the RAG vs long context topic).","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w05-t02","order":2,"group":"Baseline","title":"Lexical and sparse retrieval (BM25, SPLADE)","summary":"Lexical retrieval matches the words of the query against an inverted index and scores with BM25. Learned sparse models such as SPLADE keep the inverted index but learn which terms matter.","useIf":"Users search with identifiers, names, codes, dates or jargon, or you need explainable matches and no embedding cost.","avoidIf":"Queries are paraphrases that share few words with the documents and nothing else covers vocabulary mismatch.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w05-t03","order":3,"group":"Baseline","title":"Dense vector retrieval","summary":"Dense retrieval embeds the query and every chunk into vectors and returns the nearest chunks. It matches meaning rather than words, and it always returns neighbours, relevant or not.","useIf":"Users paraphrase, describe symptoms in their own words or search across languages, and the documents use different vocabulary.","avoidIf":"Queries hinge on rare entities, codes or exact strings and you have no keyword leg beside the vectors.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w05-t04","order":4,"group":"Baseline","title":"Hybrid search and RRF","summary":"Hybrid search runs keyword and vector retrieval in parallel and merges the ranked lists. Reciprocal rank fusion (RRF) merges by rank, so incomparable scores never need normalising.","useIf":"Query traffic mixes exact identifiers with paraphrases, and you want one ranked list without tuning score scales.","avoidIf":"All queries are of one kind, or you have labelled data and a tuned convex combination measurably beats RRF.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w05-t05","order":5,"group":"Ranking","title":"Rerankers","summary":"A reranker rescoring a shortlist with a model that reads query and chunk together. It improves order, not recall: it cannot find chunks the first stage missed.","useIf":"The right chunk is usually in the shortlist but not at the top, and you can afford extra latency and cost per query.","avoidIf":"The right chunk is not in the candidate set, or the latency budget leaves no room for a second model pass.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w05-t06","order":6,"group":"Ranking","title":"Score thresholds and abstention","summary":"A cutoff decides which retrieved chunks the model may see, and abstention is what the system does when nothing clears the bar. Both depend on scores that are not probabilities.","useIf":"Wrong answers cost more than missing answers, or your corpus cannot answer every question users ask.","avoidIf":"You would rely on a hard-coded score constant that nobody recalibrates, or you have no labelled unanswerable queries to test it on.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w05-t07","order":7,"group":"Query transformation","title":"Query rewriting","summary":"Query rewriting turns what the user typed into what the index can match: cleaned, expanded or made standalone using the conversation. It also adds a model call and the risk of changing the meaning.","useIf":"Queries are short, vague, full of pronouns from earlier turns or use different vocabulary from the documents.","avoidIf":"Queries are identifiers or exact phrases that a rewrite could paraphrase away, or the latency budget is tight.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w05-t08","order":8,"group":"Query transformation","title":"HyDE (hypothetical document embeddings)","summary":"HyDE asks a model to write a hypothetical answer, embeds that answer instead of the question, and retrieves the real documents nearest to it.","useIf":"Queries are short or phrased unlike the documents, you have no relevance labels to fine-tune with, and the model knows the domain.","avoidIf":"The domain is proprietary or full of identifiers the model would invent, or the latency budget cannot absorb a generation before retrieval.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w05-t09","order":9,"group":"Query transformation","title":"Multi-query and step-back","summary":"Multi-query fans one question out into several variants, retrieves for each and fuses the results. Step-back adds a more general question so the retriever also finds background and principles.","useIf":"Recall is low because a single phrasing misses relevant chunks, or the answer depends on a general principle the specific question does not name.","avoidIf":"Precision is the problem, the question is multi-part (use decomposition), or each extra search is too costly.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w05-t10","order":10,"group":"Query transformation","title":"Decomposition and multi-hop retrieval","summary":"Decomposition splits a compound question into sub-questions. Multi-hop retrieval chains searches, where each hop depends on what the last one found. Both need stop conditions.","useIf":"A question has several parts, or its answer needs a fact that you can only look up after finding another fact.","avoidIf":"Questions are single-fact lookups, or you cannot bound hops, tokens and time.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w05-t11","order":11,"group":"Query transformation","title":"Metadata filters and self-query","summary":"Self-query lets a model turn a natural-language question into a semantic query plus a structured metadata filter. The filter is model output, so it must be validated and must never replace authorization.","useIf":"Questions carry implicit constraints such as year, product, region or document type, and your chunks carry those fields as metadata.","avoidIf":"A filter would decide who may see data, or the metadata is sparse, inconsistent or unknown to the model.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w05-t12","order":12,"group":"Advanced patterns","title":"GraphRAG and LazyGraphRAG","summary":"GraphRAG builds an entity graph and community summaries so a system can answer whole-corpus questions that top-k chunks cannot. LazyGraphRAG defers the expensive model work to query time.","useIf":"Users ask global or thematic questions such as 'what are the main themes across these reports?', or answers require linking entities across documents.","avoidIf":"Questions are single-fact lookups, the corpus changes quickly, or per-user permissions apply inside community summaries.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w05-t13","order":13,"group":"Advanced patterns","title":"Agentic retrieval and Foundry IQ","summary":"Agentic retrieval in Azure AI Search plans focused subqueries with an LLM, runs them in parallel across knowledge sources and merges the reranked results. Foundry IQ packages knowledge bases for agents.","useIf":"Questions are multi-part or depend on chat history, you can accept preview features and an extra planning call, and you want an activity log and references.","avoidIf":"You need GA-only features beyond minimal extractive retrieval, questions are single-fact lookups, or latency leaves no room for planning.","minutes":10,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w05-t14","order":14,"group":"Advanced patterns","title":"Corrective and self-reflective RAG (CRAG, Self-RAG)","summary":"Corrective RAG scores retrieved documents and changes course when they look weak. Self-RAG trains one model to decide when to retrieve and to critique passages and its own output.","useIf":"Retrieval quality varies by question, the corpus has gaps, and a wrong answer costs more than an extra model call.","avoidIf":"Latency and cost are tight, retrieval is already reliable, or you cannot bound the retry loop.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w05-t15","order":15,"group":"Advanced patterns","title":"RAG vs long context vs cache-augmented generation","summary":"Three ways to put knowledge in front of a model: retrieve chunks per query, send the whole corpus every time, or preload and cache it. Corpus size, update rate and access model decide.","useIf":"You are deciding whether you need a retrieval stack at all, or whether a long prompt or a cached preload is enough.","avoidIf":"You would pick on a vendor's context-window headline alone, without testing accuracy at your corpus size and measuring cost per query.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w05-t16","order":16,"group":"Output and debugging","title":"Citations and answer formatting","summary":"Citations tie each claim to the source text it came from. They prove provenance, not correctness, so a good design adds span-level pointers, a verification step and a UI that lets users check.","useIf":"Answers must be traceable for trust, audit or compliance, or users need to verify claims quickly.","avoidIf":"You would treat the presence of a citation as proof that the answer is supported.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w05-t17","order":17,"group":"Output and debugging","title":"Debugging a bad RAG answer","summary":"Trace a bad answer from symptom to component. Check the evidence first, then retrieval, ranking, context assembly and generation, one stage at a time.","useIf":"An answer is wrong, missing, stale or unsupported, and you need to know which stage to fix before changing anything.","avoidIf":"You would tune prompts or swap models before looking at what was retrieved.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":3}],"quizCount":73,"flashcardCount":72,"refCount":55,"topicCount":17,"scenarioCount":39,"file":"content/w05.js"},{"id":"w06","order":6,"region":"knowledge","title":"RAG Guardrails","short":"Guard the answer","tagline":"The model will answer anyway. Decide what it may say, what it may read and what it may do.","story":"The right chunks reached the model, and the model is about to answer. It will answer fluently whether or not the chunks support it. A retrieved page may carry hidden instructions, the user may probe for harmful output, and a tool call may leave the building. This world places guards around the whole path, prices their errors and chooses between platform services, open source and custom checks.","oneLiner":"Place guards on input, retrieval, tools and output, enforce grounding, and measure what each guard costs in latency and false alarms.","minutes":100,"prereqs":["w05"],"levels":[{"id":"w06-l1","order":1,"title":"Place the guards where the damage happens","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"The model will answer whatever it is given. Checks can stand on the way in, on retrieved content, on tool calls and on the way out. Which do you need, how many can the latency budget carry, and what may reach the user while text streams?"},{"id":"w06-l2","order":2,"title":"Grounded or silent: make every claim earn its place","kind":"problem","minutes":17,"quizCount":4,"hasDefend":false,"brief":"The retriever handed over three chunks and the model wrote five confident sentences. Which of them does the evidence support, and what should happen to the rest?"},{"id":"w06-l3","order":3,"title":"Read the platform guards by status","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"Azure AI Content Safety and Foundry guardrails ship classifiers for harm, jailbreaks, document attacks, protected material and groundedness. Which are on by default, which are preview or retired, and where does each stop covering you?"},{"id":"w06-l4","order":4,"title":"Build, borrow or buy: open-source, custom and PII guards","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"The platform guards cover the common harms. Your taxonomy, your languages or your data-residency rules may say otherwise. When do you reach for NeMo Guardrails, Guardrails AI, Llama Guard, plain deterministic checks or a PII detector?"},{"id":"w06-l5","order":5,"title":"Price the false alarms and test the guards","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"A guard that blocks too much is a quiet outage, and one that blocks too little is a headline. How do you put a price on each error and test a guard before users meet it?"},{"id":"w06-l6","order":6,"title":"Boss: guard a regulated assistant","kind":"boss","minutes":18,"quizCount":3,"hasDefend":true,"brief":"An interviewer asks you to design the guardrail stack for an assistant that answers customers' questions about their own regulated account data, using RAG and a few tools. No dials are given."}],"topics":[{"id":"w06-t01","order":1,"group":"Placement","title":"Guardrail placement: input, retrieval, output, tool","summary":"A guard only sees what passes through its position. Input, retrieved content, tool calls and output each carry different risks, so placement decides what a guard can catch and what it costs in latency.","useIf":"You are deciding where to put checks around a RAG or agent request and how much latency each may add.","avoidIf":"You treat guardrails as one filter on the final answer: that misses untrusted documents, tool side effects and early leaks.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w06-t02","order":2,"group":"Grounding","title":"Groundedness and faithfulness checks","summary":"A groundedness check asks whether every claim in an answer is supported by the evidence the model was given. It is a separate question from whether the answer is true, relevant or cited.","useIf":"Wrong answers are costly and you can afford a second pass over the answer and its evidence.","avoidIf":"Latency is tight and the domain is low risk: a prompt that permits \"I don't know\" and a sampled offline check may be enough.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w06-t03","order":3,"group":"Grounding","title":"Citation enforcement, abstention and answerability","summary":"Answerability decides whether the evidence can answer at all, citation enforcement forces each claim to point at a source span, and abstention is the safe response when it cannot.","useIf":"A confident wrong answer costs more than \"I could not find that\", and users or auditors need to trace claims to sources.","avoidIf":"The assistant is a creative or brainstorming tool where no source of truth exists.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w06-t04","order":4,"group":"Azure AI Content Safety","title":"Harm categories and severities","summary":"Azure AI Content Safety classifies text and images into four harm categories with severity levels. A guardrail control compares the severity to a threshold you choose, so the threshold is your false-positive dial.","useIf":"You need a managed first line of defence for hate, sexual, violence and self-harm content in prompts and completions.","avoidIf":"Your risk is a custom policy (for example investment advice) or prompt injection: these categories do not cover them.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w06-t05","order":5,"group":"Azure AI Content Safety","title":"Prompt Shields","summary":"Prompt Shields detects two attack families: user prompt attacks typed by the caller and document attacks hidden in content the model reads. It is a probabilistic classifier, one layer of a defence in depth.","useIf":"Your model reads text you do not control: user input, retrieved documents, web pages, emails or tool output.","avoidIf":"You expect it to be a complete defence: pair it with least privilege, Spotlighting where available and deterministic blocks on exfiltration paths.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w06-t06","order":6,"group":"Azure AI Content Safety","title":"Groundedness detection and protected material","summary":"Two Content Safety checks guard the output: groundedness detection compares an answer with its sources, and protected material detection flags known copyrighted text and code. Their status and limits decide where you can use them.","useIf":"You need managed output checks for unsupported claims or reproduced copyrighted content and can live with their language, size and release-state limits.","avoidIf":"Your traffic is not English or your content exceeds the size limits: both features were tested on English only.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w06-t07","order":7,"group":"Azure AI Content Safety","title":"Platform guardrails in Azure OpenAI and Foundry","summary":"A Foundry guardrail is a named set of controls. Each control names a risk, the intervention points to scan and an action. Models and agents follow different rules, and streaming mode decides when violating text can appear.","useIf":"You deploy models or agents in Microsoft Foundry and want managed filtering configured as policy, not code.","avoidIf":"Your agents run outside Foundry Agent Service or your policy needs custom taxonomies: guardrails do not cover other registered agents.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w06-t08","order":8,"group":"Alternatives and operations","title":"Open-source guard frameworks","summary":"NeMo Guardrails orchestrates rails around an LLM, Guardrails AI runs validators on inputs and outputs, and Llama Guard is a safety classifier model. You self-host them when data location, taxonomy or language rule out the managed service.","useIf":"Data cannot leave your environment, your policy taxonomy is custom, or you need flow control and validation logic the platform guardrails do not offer.","avoidIf":"A managed guardrail already meets the need: self-hosting adds GPUs, evaluation work and upgrade churn.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w06-t09","order":9,"group":"Alternatives and operations","title":"PII detection and redaction","summary":"PII handling means detecting personal data, then choosing to redact, mask or tokenise it at the right points: ingest, input, output and logs. Detectors are imperfect, so the choice of point and method matters as much as the tool.","useIf":"Prompts, documents, transcripts or logs contain personal data that the model, the index or the log store should not hold.","avoidIf":"You plan to rely on a single output filter: it misses PII that was already sent to the model and written to logs.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w06-t10","order":10,"group":"Alternatives and operations","title":"Guard latency, cost and false positives","summary":"Every guard adds latency and cost and blocks some innocent requests. You manage that by running independent guards in parallel, tiering them by risk, and measuring false positives in shadow mode before you enforce.","useIf":"You are adding guards to a live assistant and must keep response time, spend and wrongful blocks inside agreed budgets.","avoidIf":"You treat a guard's accuracy claims as your measured quality: only your own labelled traffic tells you the real error rates.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3}],"quizCount":49,"flashcardCount":50,"refCount":31,"topicCount":10,"scenarioCount":20,"file":"content/w06.js"},{"id":"w07","order":7,"region":"knowledge","title":"RAG Security and ACLs","short":"Secure RAG","tagline":"The model can only leak what retrieval hands it.","story":"The question has been embedded, matched and ranked, and a set of chunks is about to enter the prompt. Some chunks belong to people who should never see them, and some contain instructions written by strangers. Here you decide who enforces access, where, and how you prove it still holds after a permission changes.","oneLiner":"Enforce access in retrieval with the caller's identity, treat every retrieved word as hostile, and test revocation like a feature.","minutes":160,"prereqs":["w03","w05"],"levels":[{"id":"w07-l1","order":1,"title":"Follow the leak","kind":"problem","minutes":20,"quizCount":4,"hasDefend":false,"brief":"A chunk of text is about to enter a prompt, and the model can only leak what retrieval hands it. Before you pick a control, find every place that text can land, who could have written it, and what the client does with the answer."},{"id":"w07-l2","order":2,"title":"Who is asking?","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Every access decision needs two inputs: who the caller is and which groups they hold when the query runs. Decide how you get them, how fresh they must be and which identity the retriever runs as, while group counts, nesting and revocation speed are still open."},{"id":"w07-l3","order":3,"title":"Pick the wall","kind":"problem","minutes":25,"quizCount":4,"hasDefend":false,"brief":"A chunk is about to be returned. Who decides whether this caller may see it: the index, your code, the source system or the shape of your infrastructure? Access selectivity, rule richness, revocation speed and where the content lives are all still open."},{"id":"w07-l4","order":4,"title":"Break the filters","kind":"lab","minutes":25,"quizCount":4,"hasDefend":false,"brief":"Numbers beat opinions. Starve a post-filter, squeeze a pre-filter's recall, leak a revoked grant, then look for the copies of your data that live outside the ACL: caches and logs."},{"id":"w07-l5","order":5,"title":"Four native paths in Azure AI Search","kind":"problem","minutes":25,"quizCount":4,"hasDefend":false,"brief":"Azure AI Search offers four document-level approaches, and three are preview as of 2026-10-13. Choose by where the content lives, how fast permissions must propagate and whether preview is allowed, then label every choice honestly."},{"id":"w07-l6","order":6,"title":"Keep it true: sync, drift and revocation","kind":"problem","minutes":22,"quizCount":4,"hasDefend":false,"brief":"Permissions change after the index is built: people leave, folders move, groups are renamed. Decide how a change reaches every copy, how you detect the ones it missed, and how you prove revocation works before a user proves it does not."},{"id":"w07-l7","order":7,"title":"Boss: design the wall, then handle the leak","kind":"boss","minutes":25,"quizCount":3,"hasDefend":true,"brief":"An interviewer asks you to design access control for a RAG assistant, with every dial unspecified, and then reports a leak. Practise the five steps of Dial-and-Defend: clarify, list options, pick and flip, name failures, name metrics and rollout."}],"topics":[{"id":"w07-t01","order":1,"group":"Threats","title":"RAG threat model and OWASP LLM Top 10 2025","summary":"A threat model for RAG lists what you protect, who can write into each stage and where text crosses a trust boundary, then maps those risks to the OWASP LLM Top 10 2025 ids.","useIf":"You are starting a RAG design review and need a shared vocabulary for what can go wrong.","avoidIf":"You already have a threat model and need a specific control. Jump to the access control or defence topics.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w07-t02","order":2,"group":"Threats","title":"Indirect prompt injection via documents","summary":"An attacker hides instructions in a document, email or web page that retrieval later places in the prompt, and the model may follow them as if the user had written them.","useIf":"Any text written by someone other than the caller can reach the prompt.","avoidIf":"You are looking for typed attacks by the caller. That is direct injection, which has different defences.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t03","order":3,"group":"Threats","title":"Data poisoning","summary":"An attacker writes a few documents so that retrieval returns them for chosen questions and the model repeats their false content. No hidden instruction is needed.","useIf":"Anyone outside your editorial control can add or change content that gets indexed.","avoidIf":"You need injection defences for hidden commands. Poisoning corrupts facts, so the controls differ.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t04","order":4,"group":"Threats","title":"Embedding and vector weaknesses","summary":"Vector stores add risks of their own: cross-tenant leaks from missing filters, text recovered from embeddings, and poisoned vectors. OWASP covers them as LLM08.","useIf":"Your index holds embeddings of private text, or several tenants and apps share one vector store.","avoidIf":"You are choosing an ACL pattern. Use the access control topics and treat this as the threat background.","minutes":7,"difficulty":"advanced","scenarioCount":3,"quizCount":2},{"id":"w07-t05","order":5,"group":"Threats","title":"Exfiltration and sensitive disclosure through output","summary":"Data leaves through what the model writes: Markdown images and links that the client fetches, secrets pasted into answers, and a system prompt used as a control.","useIf":"The model sees any private data and its output is rendered, forwarded or passed to tools.","avoidIf":"You need to decide who may read which document. That is access control, which comes before output control.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t06","order":6,"group":"Access control options","title":"The ACL decision space","summary":"Five ways to keep unreadable chunks away from a caller: post-filter, pre-filter, physical isolation, live source check and delegation to the source. Four dials choose among them.","useIf":"You must pick where document permissions are enforced and want to see how the choice flips.","avoidIf":"You already know the mechanism and need its details. Open the topic for that option.","minutes":10,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t07","order":7,"group":"Access control options","title":"Post-filtering","summary":"Retrieve the top candidates first, then drop the ones the caller may not read. It is simple, and it fails when most candidates are denied.","useIf":"Nearly every document is visible to nearly every caller, or the index cannot filter on permissions.","avoidIf":"Access is selective: a caller sees a few percent of the corpus, or denied text must never leave the index.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t08","order":8,"group":"Access control options","title":"Pre-filtering with security filters","summary":"Each chunk stores the identities allowed to read it, and the app adds a search.in filter built from the caller's identities. The engine filters before it ranks. This is the GA, any-API-version pattern in Azure AI Search.","useIf":"Permissions map to users or groups that you can copy onto every chunk, and a sync lag of minutes to hours is acceptable.","avoidIf":"Revocation must take effect in seconds, or access is decided by rules (deny, sharing links) that cannot be flattened into allow lists.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t09","order":9,"group":"Access control options","title":"Tenant and user isolation: index per tenant, shared index, per-user namespaces","summary":"Isolation can be physical (a service, index or namespace per tenant or user) or logical (a shared store with a mandatory filter). The choice depends on tenant count, size skew, contracts and service limits.","useIf":"Tenants or users must not see each other's data and you must choose the boundary: service, index, namespace or filter.","avoidIf":"Your question is who can read which document inside one tenant. That is the ACL options, not tenancy.","minutes":9,"difficulty":"core","scenarioCount":4,"quizCount":2},{"id":"w07-t10","order":10,"group":"Access control options","title":"Live source permission checks","summary":"After retrieval, ask the system of record whether this caller may read each candidate right now. It gives the freshest answer, at the price of latency, load and failure handling.","useIf":"Rights are per document or rule-based, change quickly and are owned by another system.","avoidIf":"Query volume is high and the source cannot take a call per hit, or an index-side filter already meets the revocation target.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t11","order":11,"group":"Access control options","title":"Azure AI Search ACL and RBAC scopes","summary":"Preview as of 2026-10-13: permission fields on the index (userIds, groupIds, rbacScope) are enforced at query time from the user's Entra token, with Microsoft Graph expanding group membership.","useIf":"Content is in ADLS Gen2, Blob or SharePoint with Entra identities, preview is acceptable and you want to avoid writing group-expansion code.","avoidIf":"You need GA, a non-Entra identity system, deny rules or revocation faster than your sync can deliver.","minutes":10,"difficulty":"advanced","scenarioCount":4,"quizCount":3},{"id":"w07-t12","order":12,"group":"Access control options","title":"Purview sensitivity labels and SharePoint ACLs","summary":"Preview as of 2026-10-13: Azure AI Search can enforce Purview sensitivity labels and ingest SharePoint permissions with the content. Each carries limits on link types, guests, tenants and freshness.","useIf":"Content lives in SharePoint, OneLake or Blob and access follows Microsoft 365 permissions or sensitivity labels.","avoidIf":"You need GA, support for guests and Anyone links, or multi-tenant label enforcement.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":2},{"id":"w07-t13","order":13,"group":"Identity","title":"On-behalf-of flow and retrieval identity","summary":"Run retrieval as the user, not as a broad service account. In the Microsoft identity platform the on-behalf-of (OBO) flow lets a middle tier exchange the caller's token for a downstream token that carries the user's rights.","useIf":"Each caller has different rights and downstream systems (Search, Graph, a data API) must see who is asking.","avoidIf":"The job has no user, such as a scheduled batch. There you need a scoped app identity, not OBO.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t14","order":14,"group":"Identity","title":"Entra groups: overage and nested groups","summary":"A token lists at most 200 groups (JWT), so large users arrive without a groups list. Nested groups need transitive lookups. Both decide whether your ACL filter sees the user's real groups.","useIf":"Your ACLs or security filters refer to Microsoft Entra groups and some users belong to many or nested groups.","avoidIf":"Authorization is coarse and fits a few app roles. Roles avoid the overage problem.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":2},{"id":"w07-t15","order":15,"group":"Operations and defences","title":"ACL sync, drift and revocation","summary":"Every copy of a permission (index, membership cache, answer cache) ages. Design how a change reaches each copy, how you detect copies that missed it, and what revocation time you promise per tier.","useIf":"Permissions live in a source system and your index, caches or membership store hold copies of them.","avoidIf":"You delegate retrieval to the source and keep no copy. Then there is nothing to sync, only a live call to rely on.","minutes":10,"difficulty":"advanced","scenarioCount":4,"quizCount":3},{"id":"w07-t16","order":16,"group":"Operations and defences","title":"Cache and log leakage","summary":"Caches and logs hold copies of permissioned content outside the ACL. A semantic cache can answer one user from another user's retrieved documents, and a content log can expose what the index protected.","useIf":"You cache answers, embeddings or prompts, or you log prompts, chunks or responses.","avoidIf":"You have no cache and log identifiers only. Then this topic is already satisfied.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t17","order":17,"group":"Operations and defences","title":"Spotlighting and prompt-injection defences","summary":"Prompt-injection defences come in two kinds: probabilistic ones (spotlighting, Prompt Shields, hardened prompts) that lower attack success, and architectural ones that remove what an attack could use. You need both, and you need to know each one's limit.","useIf":"Untrusted text (documents, web pages, tool results) reaches the model and you must pick and layer defences.","avoidIf":"You expect one guard to solve injection. None does.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":2},{"id":"w07-t18","order":18,"group":"Operations and defences","title":"Least privilege and output controls","summary":"Give each identity and tool the minimum it needs, treat model output as untrusted, and put a human in front of actions that are costly or irreversible. Limits on what an attack can do matter more than perfect detection.","useIf":"Your assistant calls tools, writes to systems or runs with a service identity.","avoidIf":"You are choosing the document ACL mechanism. Least privilege sits around it and does not replace it.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w07-t19","order":19,"group":"Operations and defences","title":"Testing access control","summary":"Prove access control and revocation end to end with canary documents and test principals, red-team the retrieval path against named attack techniques, and keep a leak-response runbook you have rehearsed.","useIf":"You operate a RAG system over permissioned content and need evidence that revocation and isolation work.","avoidIf":"You only need the mechanism of one ACL option. Use the access control topics first.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":2}],"quizCount":67,"flashcardCount":79,"refCount":57,"topicCount":19,"scenarioCount":59,"file":"content/w07.js"},{"id":"w08","order":8,"region":"agents","title":"Tools and MCP","short":"Tools and MCP","tagline":"Give the model hands, then decide who holds the keys.","story":"The question has reached a model that can reason but cannot act. Tools are its hands, and the Model Context Protocol (MCP) is the socket they plug into. Here the trouble is practical: two protocol eras that behave differently, catalogs that eat the context window, and tool descriptions written by strangers that the model reads as instructions.","oneLiner":"Learn how MCP exposes tools, resources and prompts, how the stateful 2025-11-25 model differs from the stateless 2026-07-28 revision, and how to secure and scale a tool platform.","minutes":126,"prereqs":["w01"],"levels":[{"id":"w08-l01","order":1,"title":"Give the model hands","kind":"concept","minutes":14,"quizCount":4,"hasDefend":false,"brief":"A model can reason but cannot act, and many teams own the systems it must reach. The number of hosts, the number of servers and who decides what runs are all still open. Pick the right primitive for each capability."},{"id":"w08-l02","order":2,"title":"Tools worth calling","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Agents you do not control pick your tools from names and descriptions alone. The tool count, the result sizes and whether prompt caching is on are not fixed. Design the definition, the result and the catalog so the model succeeds and the bill stays sane."},{"id":"w08-l03","order":3,"title":"One protocol, two eras","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Hosts and servers in your estate sit on different MCP revisions, and a plain load balancer fronts the servers. You must decide which era to build for and how old and new peers connect. The client mix, the fleet shape and any need for server-initiated requests are open."},{"id":"w08-l04","order":4,"title":"Ask, wait and listen","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"A tool needs a human answer halfway through, or it runs for ten minutes while the client may disconnect. The expected duration, whether secrets are involved and whether the client supports extensions are open. Choose how the call pauses, waits and reports changes."},{"id":"w08-l05","order":5,"title":"Who is calling whom","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Your MCP server fronts internal APIs. Some callers are people in a host application and some are unattended jobs. The identity provider, whether admins need central control and whether the server calls downstream APIs as the user are all open. Decide how callers authenticate and which tokens the server accepts."},{"id":"w08-l06","order":6,"title":"Guard the catalog","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Dozens of teams will publish MCP servers and every agent will read their descriptions as if they were instructions. The number of teams, the need for central policy and whether you need more than tools are open. Decide where trust is checked and whether a gateway, a bundle or a proxy of your own owns the catalog."},{"id":"w08-l07","order":7,"title":"Boss: build the tool platform","kind":"boss","minutes":22,"quizCount":4,"hasDefend":true,"brief":"An interviewer asks you to design a tool platform that many agents and teams will share. They give you nothing else. Run the Dial-and-Defend method: clarify, list options, choose, name failure modes, then metrics and rollout."}],"topics":[{"id":"w08-t01","order":1,"group":"Foundations","title":"Why MCP: hosts, clients and servers","summary":"The Model Context Protocol is an open JSON-RPC 2.0 protocol that lets any AI application (host) discover and use capabilities owned by separate servers, so integrations are written once per side instead of once per pair.","useIf":"Several AI applications must reach the same systems, or the team that owns a capability is not the team that builds the agent.","avoidIf":"One application in one codebase calls a few functions it owns, so a protocol boundary adds hops and auth work for no reuse.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w08-t02","order":2,"group":"Foundations","title":"Tools","summary":"A tool is a function a server advertises with a name, description and JSON Schema. The model decides when to call it with `tools/call`, and the result flows back as content, structured content or an error the model can act on.","useIf":"The model must take an action or fetch data on demand, and you can describe the inputs with a schema.","avoidIf":"The data is static context a host should attach itself (a resource) or a user-picked workflow (a prompt).","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w08-t03","order":3,"group":"Foundations","title":"Resources and resource templates","summary":"Resources are context data a server exposes by URI. The host application decides what to attach, and resource templates let it address a whole family of items with a URI pattern.","useIf":"You have documents, schemas, files or records that a host or user should be able to browse and attach as context.","avoidIf":"The model must decide on its own which data to fetch and when, since nothing attaches a resource unless the host does.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w08-t04","order":4,"group":"Foundations","title":"Prompts","summary":"Prompts are reusable message templates a server offers. A user picks one, often as a slash command, fills its arguments, and the server returns ready-made messages.","useIf":"You want a person to start a standard workflow with one action and consistent wording across a team.","avoidIf":"Nobody is present to pick it, such as an unattended agent, or the model should choose the workflow itself.","minutes":6,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w08-t05","order":5,"group":"Foundations","title":"Tool annotations, output schemas and structured content","summary":"Annotations are behaviour hints about a tool, `outputSchema` declares the shape of its result, and `structuredContent` carries machine-readable output next to the text the model reads.","useIf":"Hosts need hints for approval UX, or downstream code needs typed results from a tool.","avoidIf":"You would rely on annotations for security decisions about a server you do not control.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w08-t06","order":6,"group":"Client features","title":"Elicitation","summary":"Elicitation lets a server ask the user a question in the middle of a request, through the client. Form mode collects simple structured input and URL mode sends the user out of band for anything sensitive.","useIf":"A tool needs a missing, non-secret answer or a user consent that only a person can give, and the client declares support.","avoidIf":"You would collect passwords, API keys, tokens or payment data in a form, or no client capability exists and nobody can answer.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w08-t07","order":7,"group":"Client features","title":"Sampling and roots","summary":"Sampling let a server borrow the client's model and roots let a client tell a server which folders matter. Both are Deprecated in 2026-07-28 but still work, so know what they did and how to migrate.","useIf":"You maintain a server or client that already uses them and need a migration plan before the earliest removal.","avoidIf":"You are starting a new design. New implementations SHOULD NOT adopt either feature.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w08-t08","order":8,"group":"Client features","title":"Multi round-trip requests and Tasks","summary":"Multi Round-Trip Requests (MRTR) let a stateless server pause a call to ask for input by returning `input_required`. The Tasks extension gives long-running work a durable handle that clients poll.","useIf":"A tool needs a human answer mid-call (MRTR), or work outlasts a connection and must survive disconnects (Tasks).","avoidIf":"The call finishes in seconds with all inputs known, or the client does not support the extension and a start-and-poll pair of tools is simpler.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w08-t09","order":9,"group":"Transports and spec","title":"Transports: stdio and Streamable HTTP","summary":"MCP defines two transports. stdio runs a server as a local subprocess for one client. Streamable HTTP serves many clients from one endpoint. The older HTTP+SSE transport is Deprecated.","useIf":"You must decide how a host reaches a server: spawn it locally, or call it as a shared network service.","avoidIf":"You are tempted to start new work on HTTP+SSE or to put secrets on a local HTTP port with no Origin check.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":2},{"id":"w08-t10","order":10,"group":"Transports and spec","title":"Stateful vs stateless revisions","summary":"Through 2025-11-25 an MCP connection was a stateful session opened by `initialize`. The 2026-07-28 revision removes the handshake and session id, sends version and capabilities with every request and makes `server/discover` mandatory.","useIf":"You build or run servers and clients across both eras, or must choose which revision to target.","avoidIf":"You assume a 2026-07-28 client can talk to a 2025-11-25-only server. It cannot without fallback logic.","minutes":10,"difficulty":"advanced","scenarioCount":3,"quizCount":2},{"id":"w08-t11","order":11,"group":"Security","title":"MCP authorization: OAuth 2.1, PRM, CIMD vs DCR","summary":"A protected MCP server is an OAuth 2.1 resource server. Clients find its authorization server through protected resource metadata, register with a client ID metadata document, run authorization code with PKCE and send an audience-bound token on every request.","useIf":"You expose or consume a remote MCP server that must know which user or application is calling.","avoidIf":"The server is a local stdio process. The spec says stdio servers SHOULD NOT follow this flow and should read credentials from the environment.","minutes":10,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w08-t12","order":12,"group":"Security","title":"Token passthrough and the confused deputy","summary":"An MCP server must never accept or forward a token that was not issued for it. Proxies with a static client ID must also get per-client consent, or an attacker can use the user's earlier consent to steal an authorization code.","useIf":"Your MCP server calls downstream APIs, sits behind a gateway, or proxies a third-party OAuth provider.","avoidIf":"You are tempted to forward the caller's token downstream because 'it is all inside our network'.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w08-t13","order":13,"group":"Security","title":"Tool poisoning, rug pulls and SSRF","summary":"Tool descriptions, annotations and results are text the model reads, so a malicious or changed server can steer it. OAuth discovery also makes clients fetch URLs a server controls. Defend with pinning, review, least privilege and network controls.","useIf":"You connect hosts to servers you do not fully control, or run clients server-side.","avoidIf":"You treat tool metadata as trusted because the server is popular or the description is hidden from users.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w08-t14","order":14,"group":"Design and operations","title":"Tool design and token cost","summary":"Every tool definition and every tool result costs tokens and shapes the model's choices. Good tools have few, well-named, task-shaped operations, unambiguous parameters and bounded, meaningful results.","useIf":"You are writing or reviewing tools, or an agent picks the wrong tool, runs slowly or costs too much per turn.","avoidIf":"You expose one tool per API endpoint because the API already looks that way.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w08-t15","order":15,"group":"Design and operations","title":"Scaling tool catalogs: tool search and caching","summary":"When definitions swamp the context window or hurt selection accuracy, load tools on demand through tool search or code mode, and do it without breaking the prompt cache.","useIf":"You aggregate several servers, hold dozens or hundreds of tools, or see rising token cost and wrong tool choices.","avoidIf":"You have fewer than about ten small tools used on most requests. Loading them all is simpler and keeps the cache stable.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":2},{"id":"w08-t16","order":16,"group":"Design and operations","title":"Gateways, registry and governance","summary":"As servers and agents multiply, put policy in a gateway (API Management), curated bundles behind one endpoint (Foundry Toolbox) and a catalog with an approval workflow (a private registry) instead of wiring every agent to every server.","useIf":"Several teams publish or consume MCP servers and you need central auth, limits, audit, versioning and discovery.","avoidIf":"One agent uses two servers you own. Direct connection with allowed tools and approvals is simpler.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":2},{"id":"w08-t17","order":17,"group":"Design and operations","title":"Function calling vs MCP vs OpenAPI tools","summary":"Three ways to give a model tools: functions your app defines and runs, an MCP server another party owns, or an OpenAPI tool a platform calls from a spec. Choose by reuse, ownership, auth model and latency.","useIf":"You must decide how a new capability reaches a model and who defines, runs and secures it.","avoidIf":"You treat them as rivals. Hosts convert MCP tools to function-calling format, and platforms can bundle all three.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":2}],"quizCount":62,"flashcardCount":77,"refCount":58,"topicCount":17,"scenarioCount":40,"file":"content/w08.js"},{"id":"w09","order":9,"region":"agents","title":"A2A and Interop","short":"A2A and interop","tagline":"When the work belongs to another agent, treat it as a peer, not a function.","story":"The work belongs to someone else. Another team, vendor or framework owns the agent that can finish it, and you cannot see its prompts, tools or memory. Here the traps are treating a peer like a function call, blocking on work that takes an hour, and trusting an Agent Card that anyone could have edited.","oneLiner":"Learn how the Agent2Agent protocol lets opaque agents discover each other, run tasks and exchange artifacts, and when an in-process tool, an MCP server or an A2A peer is the right boundary.","minutes":108,"prereqs":["w08"],"levels":[{"id":"w09-l01","order":1,"title":"The work belongs to someone else","kind":"problem","minutes":16,"quizCount":4,"hasDefend":false,"brief":"A job needs an agent that another team, vendor or framework owns. You cannot inspect its prompts, tools or memory. Whether you call it as a function, as an MCP tool or as a peer depends on ownership, task shape and how much of its internals you control."},{"id":"w09-l02","order":2,"title":"Read the card before you trust it","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"Before you send one message you read the callee's Agent Card. The card is a claim, not proof. How you discover it, which interface you choose and how far you verify it depend on who the callee is, what the card reveals and how often it changes."},{"id":"w09-l03","order":3,"title":"Messages, tasks and artifacts","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"A remote agent gets a request that may be a quick answer, a long job or a conversation. How it models the reply, the state and the follow-ups decides whether callers can reason about the work. Choose a response style and learn the rules that keep ids and states consistent."},{"id":"w09-l04","order":4,"title":"Wait, stream or push","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"A remote agent's job takes anywhere from two seconds to two days, and your caller may sit behind a firewall, on a phone or in a serverless function. Duration, reachability and update frequency are open. Choose how updates arrive, and learn how bindings and versions affect that choice."},{"id":"w09-l05","order":5,"title":"Trust between strangers, and the Microsoft stack","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Your agent will call agents you do not own, and others will call yours. Identity, delegation, consent and the platform you run on shape what is possible. Decide how callers authenticate, what a credential request inside a task may do, and what Foundry and Agent Framework support."},{"id":"w09-l06","order":6,"title":"Boss: connect agents you do not own","kind":"boss","minutes":22,"quizCount":4,"hasDefend":true,"brief":"An interviewer asks you to connect agents owned by different teams and vendors so they can work together on customer requests. Nothing else is specified. Run the Dial-and-Defend method: clarify, list options, choose, name failure modes, then metrics and rollout."}],"topics":[{"id":"w09-t01","order":1,"group":"Concepts","title":"Why A2A and opaque agents","summary":"A2A is an open protocol that lets independent agents, built on different stacks and owned by different teams, discover each other, exchange tasks and return results without exposing prompts, tools or memory.","useIf":"Another team, vendor or framework owns the agent you need and you can only observe its inputs and outputs.","avoidIf":"You own both agents in one process and one team, where an in-process tool call is simpler and faster.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w09-t02","order":2,"group":"Concepts","title":"A2A vs MCP vs agent-as-tool","summary":"Three ways to use another agent's work: call it as an in-process function, reach it as an MCP tool, or talk to it as an A2A peer. Ownership, task shape, trust and latency decide which.","useIf":"You must decide how one agent should reach a capability or another agent.","avoidIf":"You want one answer for the whole system: mix the three, one per boundary.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w09-t03","order":3,"group":"Protocol","title":"Agent Card and discovery","summary":"The Agent Card is a JSON document that an A2A server publishes to describe its identity, endpoints, capabilities, skills and security. Clients fetch it from a well-known URL, a registry or direct configuration.","useIf":"You publish an agent for others to call, or you must decide how a client finds and trusts a remote agent.","avoidIf":"You treat the card as proof of identity or as a contract: it is a claim that must be verified and then authenticated against.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w09-t04","order":4,"group":"Protocol","title":"Task lifecycle and states","summary":"A Task is the stateful unit of work in A2A. It moves through defined states, ends in one of four terminal states or pauses in an interrupted state that waits for the client.","useIf":"A remote agent's work takes longer than one reply or may need input, so callers need a handle to track it.","avoidIf":"The agent only returns quick, self-contained answers: reply with a direct Message and skip task state.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w09-t05","order":5,"group":"Protocol","title":"Message, Part and Artifact","summary":"A Message carries communication between client and agent, a Part is the typed content container inside messages and artifacts, and an Artifact is a deliverable produced by a task.","useIf":"You design what a remote agent sends back and must decide what goes in a message, what goes in an artifact and which part type carries it.","avoidIf":"You put task results in status messages: the spec says messages are not a reliable delivery mechanism.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w09-t06","order":6,"group":"Protocol","title":"Operations and protocol bindings","summary":"A2A defines one set of operations (send, stream, get, list, cancel, subscribe, push config, extended card) and exposes them through three functionally equivalent bindings: JSON-RPC, gRPC and HTTP+JSON.","useIf":"You implement or call an A2A endpoint and must pick a binding or debug a call across stacks.","avoidIf":"You hand-roll the wire format when an SDK exists: the SDK handles method names, headers and streaming for the binding you choose.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w09-t07","order":7,"group":"Interaction modes","title":"Streaming, polling and push notifications","summary":"A2A offers three ways to hear about task progress: poll with GetTask, stream over Server-Sent Events, or receive webhook calls (push notifications). Task duration, caller reachability and update frequency decide.","useIf":"You call or build an agent whose work outlasts a single quick reply and you must choose how updates arrive.","avoidIf":"You use a blocking SendMessage for jobs that may run for minutes: the call waits until the task is terminal or interrupted.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w09-t08","order":8,"group":"Interaction modes","title":"Long-running and input-required tasks","summary":"Long A2A tasks can pause in INPUT_REQUIRED or AUTH_REQUIRED and resume when the client replies on the same task. Clients must persist ids, choose an update mode and plan for retention and restarts.","useIf":"A remote agent's job may run for minutes to days, ask clarifying questions or need credentials mid-way.","avoidIf":"Every call finishes in one reply: skip task persistence and interrupted-state handling.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w09-t09","order":9,"group":"Security and platforms","title":"A2A authentication and trust","summary":"A2A treats agents as ordinary enterprise HTTP services: identity lives in the transport, credentials are obtained out of band, the server authenticates every request and authorizes per skill, task and data.","useIf":"Your agent calls agents you do not own, or others call yours, and you must decide how identity, delegation and trust boundaries work.","avoidIf":"You assume the Agent Card or a task state grants trust: neither authenticates or authorizes anyone.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w09-t10","order":10,"group":"Security and platforms","title":"A2A in Agent Framework and Foundry","summary":"Microsoft Agent Framework and Foundry Agent Service can both call and expose A2A agents. Foundry's a2a tool and A2A 1.0 are generally available, while the Agent Framework A2A packages are prerelease, and each has limits worth knowing.","useIf":"You build on Microsoft's stack and need agents to call, or be called by, agents on other platforms.","avoidIf":"Your agents share one process and team: Agent Framework's agent-as-tool pattern is simpler and cheaper.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3}],"quizCount":48,"flashcardCount":56,"refCount":25,"topicCount":10,"scenarioCount":21,"file":"content/w09.js"},{"id":"w10","order":10,"region":"agents","title":"Agent and Multi-Agent Patterns","short":"Agent patterns","tagline":"Choose the loop, the crew, the context and the memory on purpose.","story":"One model call is no longer enough: the question needs several steps, some tools and maybe several specialists. Every step you add costs tokens and latency and adds a new way to fail. Here you learn to add autonomy only when it earns its cost, and to keep the context, the memory and the run alive long enough to finish.","oneLiner":"Start at the lowest rung of autonomy that works, then climb only when a dial you can name forces you to.","minutes":125,"prereqs":["w08","w09"],"levels":[{"id":"w10-l1","order":1,"title":"Turn the autonomy dial","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"A request needs more than one model call, but the steps, the risk and the latency budget are not fixed yet. Decide how much control the model gets before you choose any framework."},{"id":"w10-l2","order":2,"title":"Loops with brakes","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"The model must decide its own next step, call a tool, read the result and go again. Tool reliability, plan stability and the token budget are not fixed. Choose a loop shape and decide what stops it."},{"id":"w10-l3","order":3,"title":"Soloist or crowd? Topologies and the multi-agent bill","kind":"problem","minutes":22,"quizCount":4,"hasDefend":false,"brief":"One agent is struggling, and someone proposes a team of agents. The coupling of the subtasks, the value per run, the trust boundaries and the latency budget are all undecided. Compare the topologies against the evidence before you split anything."},{"id":"w10-l4","order":4,"title":"Context is a budget, not a bucket","kind":"lab","minutes":22,"quizCount":4,"hasDefend":false,"brief":"Every step of an agent adds tokens to a window that has a hard limit and a soft quality limit. The number of tool calls, whether dropped content can be restored and whether the work branches are all open. Learn what to clear, compact, offload or isolate."},{"id":"w10-l5","order":5,"title":"Memory without regret","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"The assistant should remember things across sessions, but the personalization value, the delete rules, the network posture and the trust in whatever gets written are all undecided. Decide what to store, who may write it and how it is read back."},{"id":"w10-l6","order":6,"title":"Runs that outlive the request","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"A task will run for hours and may wait a day for a human. Run length, tool failure rate, approval delay and whether side effects can safely repeat are all open. Decide where state lives and how a run resumes."},{"id":"w10-l7","order":7,"title":"Boss: crew or soloist? Defend the topology","kind":"boss","minutes":25,"quizCount":4,"hasDefend":true,"brief":"An interviewer asks whether a research-and-report workload needs several agents and wants the topology. The dials are not given. Clarify them, compare the options, choose, and say what would flip your answer."}],"topics":[{"id":"w10-t01","order":1,"group":"Workflow patterns","title":"Workflows vs agents: the autonomy dial","summary":"A workflow keeps the control flow in your code. An agent lets the model choose its own next step. Both are agentic systems, and the autonomy dial sets how much control the model gets.","useIf":"You are deciding how much control a model gets before you pick any framework: start at the left of the dial and climb only for a reason you can name.","avoidIf":"Do not give a free loop to a task whose steps are known, and do not script an open-ended task that needs the model to adapt.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w10-t02","order":2,"group":"Workflow patterns","title":"Prompt chaining","summary":"Split a task into fixed steps. Each model call works on the previous output, and a programmatic gate between steps checks it before the chain continues.","useIf":"The task splits cleanly into known sequential subtasks and you would rather trade some latency for a more accurate result per step.","avoidIf":"Steps are independent (run them in parallel), the path depends on intermediate results, or an early error cannot be caught before later steps build on it.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t03","order":3,"group":"Workflow patterns","title":"Routing","summary":"Classify the input first, then send it down a specialised path: a different prompt, tool set, model or agent for each category.","useIf":"Inputs fall into distinct categories that are better handled separately, and a classifier can tell them apart with acceptable accuracy.","avoidIf":"Every input needs the same handling, categories overlap heavily, or a wrong route is costly and you cannot detect it.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w10-t04","order":4,"group":"Workflow patterns","title":"Parallelization","summary":"Run several model calls at the same time and combine the results. Sectioning splits a task into independent parts. Voting repeats one task to get diverse answers.","useIf":"Subtasks are independent, or you want several independent attempts at the same question, and cost and rate limits allow the extra calls.","avoidIf":"Branches need each other's output, share state they could corrupt, or you have no rule for combining conflicting results.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t05","order":5,"group":"Workflow patterns","title":"Orchestrator-workers","summary":"A lead model breaks a task into subtasks at run time, delegates them to worker calls and synthesises the results. The subtasks are not known in advance.","useIf":"The task is complex or breadth-first, the set of subtasks depends on the input, and the value per run covers the extra tokens.","avoidIf":"The subtasks are known up front (parallelise or chain them), the work is tightly coupled writes, or value per run is low.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w10-t06","order":6,"group":"Workflow patterns","title":"Evaluator-optimizer","summary":"One call generates an answer and another evaluates it against criteria. Feedback loops back to the generator until the answer passes or a stop rule fires.","useIf":"You have clear, checkable criteria and a first draft is measurably improved by feedback, so each loop earns its cost.","avoidIf":"Criteria are vague, the evaluator shares the generator's blind spots, or one pass is already good enough.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t07","order":7,"group":"Reasoning loops","title":"ReAct","summary":"ReAct interleaves reasoning with actions: the model thinks, calls a tool, reads the observation and repeats until it can answer. It is the loop inside most tool-using agents.","useIf":"The next step depends on what the last tool returned, so the path cannot be planned in advance, and each loop is affordable.","avoidIf":"The tool chain is predictable (plan first or use a workflow), latency is very tight, or tools are unreliable and nothing bounds the loop.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t08","order":8,"group":"Reasoning loops","title":"Plan-and-execute","summary":"A planner writes the steps first, then an executor carries them out, often with cheaper calls and without reasoning after every tool result. A replan step handles surprises.","useIf":"Tool chains are fairly predictable, you want a reviewable plan before side effects, or token cost per run matters more than step-by-step flexibility.","avoidIf":"Each tool result changes what you should do next, or the environment shifts faster than a plan can stay valid.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w10-t09","order":9,"group":"Reasoning loops","title":"Reflection and self-critique","summary":"The model reviews its own output or trajectory, writes down what went wrong and tries again. It helps when the critique rests on an external signal and often fails when it rests on the model's own judgement alone.","useIf":"A reliable signal exists after an attempt (tests, tool results, retrieval, a validator) that the critique can use.","avoidIf":"The only evidence is the model's own opinion of its reasoning, or latency and cost leave no room for a second pass.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w10-t10","order":10,"group":"Reasoning loops","title":"Loop guards, budgets and stop conditions","summary":"Any loop that can call a model needs brakes owned by the harness: a step cap, a token and cost budget, a deadline and repeat detection. Each brake ends the run with an explicit stop reason and a usable partial result.","useIf":"A model chooses its own next step, calls tools that cost money or time, or talks to other agents in a loop.","avoidIf":"Never skip it for an agent loop. Skip only for a fixed chain, whose length is already bounded by your code.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t11","order":11,"group":"Multi-agent","title":"Single vs multi-agent: the decision","summary":"Start with one agent. Add agents only when a named dial forces it: breadth that exceeds one context, tool overload, separate trust boundaries, or independent reads that can run in parallel.","useIf":"Someone proposes a team of agents and you must decide whether the extra cost, latency and failure modes are justified.","avoidIf":"Do not use a crew to fix a weak prompt, poor tools or missing evals, and do not parallelise coupled writes.","minutes":10,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t12","order":12,"group":"Multi-agent","title":"Supervisor pattern","summary":"A central supervisor agent talks to the user and calls specialist agents as tools. Control always returns to the supervisor, which stays accountable for the final result.","useIf":"One agent must own the outcome, audit trail and conversation, while specialists supply expertise, tools or isolated context.","avoidIf":"A specialist should take over and talk to the user directly, or every result flowing through one context would overflow it.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w10-t13","order":13,"group":"Multi-agent","title":"Handoff and swarm","summary":"In a handoff, one agent transfers control and the conversation to another agent that takes full ownership. Agents form a mesh with no central orchestrator, and each hop is a model call that can loop.","useIf":"The right specialist is not known up front, emerges during the conversation, and should talk to the user directly.","avoidIf":"The route is identifiable from the first message (use a router), you need one accountable owner, or work should run in parallel.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w10-t14","order":14,"group":"Multi-agent","title":"Group chat and debate","summary":"Several agents share one conversation, and a manager picks who speaks next until a stop rule fires. It suits review, maker-checker loops and structured debate, and it costs more with every round and every agent.","useIf":"The goal is better judgement from several perspectives on one artifact, there is an objective stop test, and the agents are mostly read-only.","avoidIf":"Plain delegation or a linear pipeline is enough, latency is tight, or nothing can say when the discussion is done.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t15","order":15,"group":"Multi-agent","title":"Dynamic task ledgers (Magentic)","summary":"A manager agent builds a task ledger of facts and a plan, tracks progress each round, picks the next specialist and replans when work stalls. It targets open-ended problems with no predetermined path.","useIf":"The problem is open-ended, the plan must emerge and be revised, and agents need tools that act on external systems.","avoidIf":"The path is deterministic, the task is time-sensitive, or you cannot afford the planning overhead and an unproven pattern.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w10-t16","order":16,"group":"Multi-agent","title":"Multi-agent failure modes","summary":"MAST, a failure taxonomy built from real traces, groups 14 failure modes into system design issues, inter-agent misalignment and task verification. Most are visible in traces if you look for them.","useIf":"You are reviewing, debugging or evaluating a multi-agent system and need a checklist of how such systems actually fail.","avoidIf":"You have one agent with no handoffs. A multi-agent taxonomy then adds little, and single-agent loop failures matter more.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w10-t17","order":17,"group":"Context and memory","title":"Context engineering","summary":"Context engineering is choosing what enters the model's window at every step: instructions, tool definitions, memory, retrieved data, history and tool results. The aim is the smallest set of high-signal tokens that makes the next step succeed.","useIf":"An agent runs many steps, uses many tools or large tool results, or the bill and latency are dominated by input tokens.","avoidIf":"Never skip it for long agent loops. For one short chat turn with a small prompt there is little to engineer.","minutes":10,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t18","order":18,"group":"Context and memory","title":"Context rot and compaction","summary":"Model quality degrades as input grows, often well below the advertised window. Control it by clearing stale tool results, offloading to files, summarising with care and isolating work in sub-agents.","useIf":"A run has many tool calls or turns, quality drops late in the run, or you approach the context limit.","avoidIf":"Do not compact short tasks, and do not use lossy summaries where exact wording, numbers or constraints must survive.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w10-t19","order":19,"group":"Context and memory","title":"Memory types","summary":"Agent memory has a short-lived working part (the context window) and long-term parts that persist: episodic (what happened), semantic (what is true) and procedural (how to do things). Name the type before you choose a store.","useIf":"An assistant should remember things across turns or sessions, and you must decide what to store, where and how it is read back.","avoidIf":"Do not add long-term memory when thread state suffices, or when you cannot meet privacy, deletion or isolation rules for what it stores.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w10-t20","order":20,"group":"Context and memory","title":"Memory policies, poisoning and privacy","summary":"A memory layer needs written policies for what gets stored, how it is read, when it expires and how it is deleted. Every write is untrusted input, because attackers can plant memories through ordinary conversation.","useIf":"An agent writes to long-term memory, or reads memory that other users, tools or web content could influence.","avoidIf":"Do not rely on a memory store that you cannot scope per user, expire, audit and delete from.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w10-t21","order":21,"group":"Long-running agents","title":"Durable execution and checkpoints","summary":"Long agent runs must keep their state outside the process, so a crash, deploy or long wait resumes from the last checkpoint instead of restarting. Checkpoints help you resume. Durable execution adds retries, timers and deterministic replay.","useIf":"A run lasts hours, waits for humans, calls flaky tools or must survive restarts and deployments.","avoidIf":"A run lasts seconds to minutes and restarting from scratch is cheap and safe. A plain in-process loop is simpler.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w10-t22","order":22,"group":"Long-running agents","title":"Human-in-the-loop patterns and idempotency","summary":"Put a person in the loop where an action is costly or irreversible, and make every side effect safe to retry with idempotency keys or compensating steps. Exactly-once is a design goal built from at-least-once delivery plus idempotent handlers.","useIf":"An agent can spend money, change data, message people or call tools whose effects cannot be undone, and runs can be retried or resumed.","avoidIf":"Do not gate every harmless read behind approval. Approval fatigue turns the gate into a rubber stamp.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3}],"quizCount":79,"flashcardCount":88,"refCount":61,"topicCount":22,"scenarioCount":44,"file":"content/w10.js"},{"id":"w11","order":11,"region":"agents","title":"Microsoft Agent Framework","short":"Agent Framework","tagline":"Pick the rung, wire the pipeline, and keep long runs alive.","story":"The team has picked a framework and still has to pick everything inside it. A plain agent, a Harness Agent and a graph workflow are three different promises about control, memory and recovery. This world shows how to choose the rung, wire the pipeline, pick the crew shape and keep a run alive across approvals and restarts.","oneLiner":"Start with the lowest rung that meets the requirement, then climb only when a dial you can name forces you to.","minutes":100,"prereqs":["w10"],"levels":[{"id":"w11-l1","order":1,"title":"Pick your rung: function, agent, Harness or workflow","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"A team has a job that may need tools, a long run or a human sign-off, and has already chosen Agent Framework. Before any code, decide which rung of the framework the job needs. The dials are not given, so name the ones that matter."},{"id":"w11-l2","order":2,"title":"Wrap the run: middleware, approvals and memory that fits","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"A request passes through several layers before the model sees it, and the transcript has to live somewhere and stay small. Decide what belongs in middleware, a context provider or a history provider, where history lives, and how it shrinks. The dials are not given."},{"id":"w11-l3","order":3,"title":"Choose the crew shape: five orchestrations and when to avoid each","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"Several agents have to cooperate on one task. Pick sequential, concurrent, handoff, group chat or Magentic, or keep one agent with specialists as tools. The dials are not given, so find the ones that decide it."},{"id":"w11-l4","order":4,"title":"Pause, crash, resume: supersteps, checkpoints and durable hosting","kind":"problem","minutes":20,"quizCount":4,"hasDefend":false,"brief":"An approval can take two days, and the host will restart in between. Decide what gets saved, where it is stored, what must be rebuilt identically on resume, and which long-running feature you are really using. The dials are not given."},{"id":"w11-l5","order":5,"title":"Boss: architect the long-running, approval-gated crew","kind":"boss","minutes":25,"quizCount":4,"hasDefend":true,"brief":"An interviewer wants a multi-agent process that drafts a change, waits up to two days for a human approval, then writes to a system of record, built on Microsoft Agent Framework. The dials are not given. Clarify them, compare the options, choose, and say what would flip your answer."}],"topics":[{"id":"w11-t01","order":1,"group":"Foundations","title":"What Agent Framework is, and its Semantic Kernel and AutoGen lineage","summary":"Microsoft Agent Framework (MAF) is the open-source SDK for building agents and graph workflows in C#, Python and Go. It is the direct successor to Semantic Kernel and AutoGen, built by the same teams.","useIf":"You build agents on the Microsoft stack (Foundry, Azure OpenAI, Entra, Azure Functions) or want one SDK for single agents, multi-agent orchestration and long-running workflows.","avoidIf":"You depend on a preview-only part (hosting, durable, AG-UI, skills) for a regulated launch and cannot absorb breaking changes, or one plain model call with a function would do the job.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t02","order":2,"group":"Foundations","title":"Agent vs Harness Agent vs Workflow","summary":"A plain agent is one model loop with tools. A Harness Agent is the same agent pre-wired for long multi-step work. A workflow is an explicit graph where you, not the model, decide the path.","useIf":"You are choosing the unit of control: model-decided path (agent or Harness) or developer-decided path (workflow).","avoidIf":"A plain function can do the task. The docs say that if you can write a function, do that instead of using an agent.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t03","order":3,"group":"Foundations","title":"Chat clients and the agent pipeline","summary":"Every agent run flows through layers: agent middleware, a context layer (history and context providers), then a chat client with its own decorators. Knowing the layer tells you where an extension belongs.","useIf":"You are deciding where to put a guardrail, memory, logging or retry, or swapping a model provider.","avoidIf":"You only call an agent with default settings and no extension points.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t04","order":4,"group":"Behaviour","title":"Middleware: agent, chat and function","summary":"Three interception points: around a whole agent run, around each model call and around each tool call. Each can inspect, change, short-circuit or replace the result.","useIf":"You need a guardrail, audit log, allow-list, rate limit or result rewrite that must apply no matter what the model decides.","avoidIf":"The rule belongs in the prompt, in tool code or in a context provider that merely adds information.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t05","order":5,"group":"Behaviour","title":"Tools and function invocation","summary":"Tools are functions the model can request. The framework runs the tool loop: model asks, framework calls the function, result goes back, until the model answers or a limit stops it.","useIf":"The agent must read data, call APIs or act, and you want the framework to run the call loop with limits and middleware.","avoidIf":"The call is deterministic and always needed: call it in code and pass the result in as context.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t06","order":6,"group":"Behaviour","title":"Tool approval and standing approvals","summary":"A tool marked for approval does not run. The run ends with an approval request, a person decides, and the next run with the same session executes or rejects the call. The Harness adds queueing and standing rules.","useIf":"A tool changes data, spends money or sends messages, and a person must authorise each class of call.","avoidIf":"The tool is read-only and cheap, or no person is available to answer: approval prompts would stall the run.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t07","order":7,"group":"Behaviour","title":"Skills","summary":"A skill is a portable folder of instructions, references and scripts (the agentskills.io format) that an agent loads on demand. Only a short description sits in the prompt until the skill is needed.","useIf":"You have reusable domain procedures (expense policy, report templates, data checks) that would bloat the system prompt if always loaded.","avoidIf":"The behaviour is one short rule that belongs in the instructions, or the API is too unstable for your release gate: the skills API is experimental.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w11-t08","order":8,"group":"Behaviour","title":"Planning, todos and agent modes","summary":"Two Harness context providers give the agent a durable to-do list and a plan or execute operating mode. The list is injected before each run so work can resume. They record progress but do not re-invoke the agent.","useIf":"A task spans many steps or sessions and you want visible progress and a human review point before autonomous work.","avoidIf":"The task fits one short run, or the steps must follow a fixed order that you can encode as a workflow.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t09","order":9,"group":"Behaviour","title":"Looping and bounded retries","summary":"A loop re-invokes an agent until a completion condition holds (marker, todos done, background tasks done, AI judge or your own callback), always with a maximum. It is experimental.","useIf":"One run often stops early and you want the agent to keep working until a checkable condition is met, within a hard cap.","avoidIf":"The condition cannot be checked cheaply and reliably, or one run is normally enough. Never loop without a cap.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w11-t10","order":10,"group":"State and memory","title":"Sessions","summary":"An agent object is stateless. An AgentSession carries the conversation state: local history or a service conversation id, plus state for context providers and Harness features. You create it, pass it on every run and persist it yourself.","useIf":"You need multi-turn conversations, approvals that span runs, todos, memory or resumption after a restart.","avoidIf":"Every request is independent and stateless: skip sessions and keep the agent single-shot.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w11-t11","order":11,"group":"State and memory","title":"History providers","summary":"A history provider loads and stores the transcript for each run. The built-in one keeps messages in the session. You can swap in a database provider, add an audit provider and choose when persistence happens.","useIf":"Conversation history must live in your own store, be audited, shrink under a reducer, or be written after every model call.","avoidIf":"The provider already manages the conversation (Foundry agents, Responses with `store` on) and you do not need local copies.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t12","order":12,"group":"State and memory","title":"Context providers and memory","summary":"A context provider runs before and after every agent run to inject instructions, messages, tools or middleware and to learn from the exchange. Memory, retrieval and dynamic instructions are all context providers.","useIf":"The agent needs knowledge it was not told in the prompt: user preferences, retrieved documents, long-term memory, per-tenant instructions or per-request tools.","avoidIf":"You need to block or rewrite a call (that is middleware), or only store the transcript (that is a history provider).","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t13","order":13,"group":"State and memory","title":"Compaction","summary":"Compaction shrinks locally held history before it hits the context limit: collapse old tool results, summarise, slide a window, truncate. Strategies work on atomic message groups and run from gentle to aggressive.","useIf":"History is held in memory (local session or your store) and long tool-heavy runs approach the model's context window or cost budget.","avoidIf":"History is service-managed (Foundry agents, Responses with `store` on, Copilot Studio): compaction has no effect there.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t14","order":14,"group":"Workflows","title":"Executors, edges and supersteps","summary":"A workflow is a directed graph: executors are the nodes, edges route typed messages between them. Execution proceeds in supersteps: all ready executors run in parallel, wait at a barrier, then the next messages are delivered.","useIf":"You want explicit order, branching, fan-out and fan-in, with deterministic ordering and clean checkpoint boundaries.","avoidIf":"The path is unknown in advance, or one agent loop can do the job without an explicit graph.","minutes":10,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t15","order":15,"group":"Workflows","title":"Shared state and checkpoints","summary":"Executors share data through workflow state and survive restarts through checkpoints written at the end of each superstep. A checkpoint holds executor state, pending messages, pending requests and shared state, and is a trust boundary.","useIf":"A workflow is long, must resume after a failure or pause, or needs audit snapshots.","avoidIf":"The workflow finishes in seconds and a rerun is cheaper than storing and securing checkpoints.","minutes":10,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w11-t16","order":16,"group":"Workflows","title":"Human-in-the-loop in workflows","summary":"An executor sends a typed request out of the workflow and waits. The caller answers with a response, and the framework routes it back. Pending requests are saved in checkpoints and re-emitted on restore, so the wait can outlive the process.","useIf":"A step needs a person or an external system to decide, approve or supply data before the graph continues.","avoidIf":"The decision is one tool approval inside a single chat turn: a tool-level approval with the same session is simpler.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t17","order":17,"group":"Workflows","title":"Workflows as agents, sub-workflows and declarative workflows","summary":"Three ways to compose and reuse workflows: expose one as an agent, nest one inside another as an executor, or define the graph in YAML instead of code.","useIf":"A graph must plug into agent-shaped hosts (A2A, Responses, AG-UI), a workflow is reusable inside larger ones, or non-developers should edit the flow.","avoidIf":"You expect middleware on the wrapper to protect inner agents, or you need complex custom logic that YAML actions cannot express.","minutes":10,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w11-t18","order":18,"group":"Orchestrations","title":"Sequential orchestration","summary":"A pipeline of agents: each one receives the conversation so far, adds its answer and passes it on. The last participant's answer is the workflow output.","useIf":"Each step builds on the previous one: draft, review, polish; translate, check, format.","avoidIf":"Steps are independent (use concurrent) or the next step depends on the content in ways a model must decide (use handoff or group chat).","minutes":6,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t19","order":19,"group":"Orchestrations","title":"Concurrent orchestration","summary":"Several agents run on the same input at the same time, then an aggregator combines their answers. Latency is about the slowest agent. Cost is the sum.","useIf":"You want independent perspectives, an ensemble or voting, and the agents do not need each other's output.","avoidIf":"Agents depend on one another, or you cannot afford multiplied token cost for a small quality gain.","minutes":6,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t20","order":20,"group":"Orchestrations","title":"Handoff orchestration","summary":"Specialist agents transfer control to each other through handoff tool calls. There is no central orchestrator: the receiving agent owns the task. It is interactive by default and returns to the user when an agent does not hand off.","useIf":"A conversation should move between specialists (triage, billing, returns) and the current specialist should own the user until it decides to hand off.","avoidIf":"A primary agent should keep ownership and only borrow help (use agent-as-tool), or work is non-interactive and fixed (use sequential or a graph).","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t21","order":21,"group":"Orchestrations","title":"Group chat orchestration","summary":"A star topology: an orchestrator picks which agent speaks next, every agent sees the shared conversation, and rounds repeat until a termination condition or round limit stops the chat.","useIf":"Several roles should iterate on one artifact (writer and reviewer, analyst and critic) under a controlled turn order.","avoidIf":"Roles are independent (concurrent), steps are strictly ordered (sequential) or ownership should transfer (handoff). Rounds multiply tokens.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w11-t22","order":22,"group":"Orchestrations","title":"Magentic orchestration","summary":"A group chat with a planning manager based on Magentic-One. The manager builds a plan, tracks progress in a ledger, picks the next agent, detects stalls, replans and synthesises the final answer.","useIf":"The solution path is not known in advance and a manager must plan, delegate and adapt across specialists over many rounds.","avoidIf":"A simpler pattern works. The docs say to use group chat when you do not need complex planning, and they warn Magentic is untested outside its original design.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w11-t23","order":23,"group":"Orchestrations","title":"Choosing an orchestration","summary":"The five built-in orchestrations differ by topology, who decides the next step and how much they cost. Start with the simplest that fits the task shape, and escalate only when evidence says it is needed.","useIf":"You have several agents and must pick sequential, concurrent, handoff, group chat or Magentic, or decide that an agent-as-tool or custom workflow is better.","avoidIf":"A single agent with tools meets quality and latency targets: multi-agent adds cost, context isolation work and failure modes.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w11-t24","order":24,"group":"Operate","title":"Background responses and durable agents","summary":"Four different things get called long-running: provider background responses (a continuation token you poll), background agents (delegated child tasks), workflow checkpoints, and the Durable Extension (durable sessions and orchestrations that wait without compute).","useIf":"A request outlives one HTTP call, a stream may break, a human may take hours, or work must survive a restart and scale across workers.","avoidIf":"Runs finish in seconds and a retry is cheap: the extra mechanisms add state, storage and operational cost.","minutes":10,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w11-t25","order":25,"group":"Operate","title":"Hosting: A2A, AG-UI, OpenAI-compatible and Foundry hosted","summary":"An agent or workflow becomes a service by choosing who owns the host: your own ASP.NET or Python server with protocol adapters (OpenAI-compatible, A2A, AG-UI), Foundry hosted agents, or the Durable Extension.","useIf":"Clients other than your own code must call the agent, and you must decide who owns routing, auth, sessions and scaling.","avoidIf":"You only run agents in-process inside an existing service and expose nothing new.","minutes":10,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w11-t26","order":26,"group":"Operate","title":"Built-in observability and evaluation hooks","summary":"Agent Framework emits OpenTelemetry spans and metrics that follow the GenAI semantic conventions. You choose the exporter and whether prompts and tool arguments are recorded. Evaluation hooks score agents and workflows locally or with Foundry evaluators.","useIf":"You must debug agent runs, attribute tokens and cost, trace across MCP and services, or gate releases on quality scores.","avoidIf":"You plan to record raw prompts in production without a privacy and retention decision: content capture is off by default for a reason.","minutes":11,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w11-t27","order":27,"group":"Operate","title":"Migrating from Semantic Kernel and AutoGen","summary":"Agent Framework collapses SK's per-service agent classes into one agent type, replaces threads with sessions, replaces plugins with plain functions and tools, and replaces AutoGen teams with graph workflows and orchestrations.","useIf":"You own Semantic Kernel agents or AutoGen teams and must plan a move inside the support window.","avoidIf":"The code is stable, out of scope for new features and inside SK's support window: migrate on a schedule, not in a panic.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":2}],"quizCount":77,"flashcardCount":99,"refCount":87,"topicCount":27,"scenarioCount":55,"file":"content/w11.js"},{"id":"w12","order":12,"region":"agents","title":"Foundry, Hosted Agents and Agent 365","short":"Foundry and Agent 365","tagline":"Give the agent a home, an identity and a paper trail.","story":"The agent works on a laptop, but it has nowhere to live and nobody knows who it is. Runtime, protocol, tool path and identity choices decide what it can reach and who answers for it. Preview labels and retirement dates move fast, so every product claim here carries the date it was checked.","oneLiner":"Choose a runtime, open the right doors, wire tools and knowledge, give the agent an identity and put it under a control plane.","minutes":120,"prereqs":["w08","w09","w11"],"levels":[{"id":"w12-l1","order":1,"title":"Pick the agent's home","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"An agent needs somewhere to run. How much code you own, where that code may run and whether each user needs private files and compute are all open. Compare five homes and flip the dials."},{"id":"w12-l2","order":2,"title":"Inside the sandbox","kind":"concept","minutes":14,"quizCount":3,"hasDefend":false,"brief":"A hosted agent's compute follows the session, not the request. Idle timeout, sandbox size and where state lives are dials you set before launch, and each one moves cost, latency or data loss."},{"id":"w12-l3","order":3,"title":"Open the right door","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"Callers speak different languages: a chat UI, a webhook, a phone line, another agent, Teams. A hosted agent can expose several protocols, so decide who owns the conversation and which channel the callers use."},{"id":"w12-l4","order":4,"title":"Hands and a library","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"The agent needs tools, knowledge and sometimes other agents. Where each one lives decides who holds the credentials, who versions the definition and where the tokens are spent."},{"id":"w12-l5","order":5,"title":"Who is this agent?","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"An agent calls APIs, reads mail and may join a group chat. Someone must be accountable and each credential must have a boundary. Choose the identity mode and the credential boundary before the permissions."},{"id":"w12-l6","order":6,"title":"Observe, govern, secure","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"Agents run on many platforms, yet an administrator must still see, govern and secure them. Decide how each agent joins the control plane and which loop keeps it healthy after launch."},{"id":"w12-l7","order":7,"title":"Boss: ship it with a name, a leash and a log","kind":"boss","minutes":22,"quizCount":3,"hasDefend":true,"brief":"An interviewer asks you to take an agent to production on Microsoft's stack and leaves every dial open. Clarify, compare, pick, name the failures and say how you will measure and roll out."}],"topics":[{"id":"w12-t01","order":1,"group":"Foundry Agent Service","title":"Foundry Agent Service map and agent types","summary":"Foundry Agent Service is a managed platform with a runtime, toolboxes, models, tracing, optimization, identity and publishing. You choose how much you build: a prompt agent, a voice prompt agent, a hosted agent, or a direct Responses API call.","useIf":"You are deciding where an agent should live in Foundry and want the map before the details.","avoidIf":"You already know the agent type and need protocol, session or identity details: jump to the specific topic.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t02","order":2,"group":"Foundry Agent Service","title":"Prompt and voice agents","summary":"A prompt agent is instructions, a model and tools stored as configuration that Foundry runs. A voice-based prompt agent adds a managed spoken conversation through Voice Live. Voice-based agents are preview.","useIf":"No custom orchestration is needed and you want nothing to build, host or scale, in text or in managed voice.","avoidIf":"You need your own code path, webhooks, custom streaming or per-session files, or you cannot accept preview limits for voice.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t03","order":3,"group":"Foundry Agent Service","title":"Hosted agents overview","summary":"A hosted agent is your own agent code, packaged as a container image or a .zip, that Foundry runs with a dedicated endpoint, a dedicated Entra identity, scaling and session state.","useIf":"You bring code, a framework, custom protocols, persistent files or need to choose compute size.","avoidIf":"Instructions, a model and tools already cover the behavior, or the code must stay on another cloud.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t04","order":4,"group":"Foundry Agent Service","title":"Hosted agent protocols","summary":"A hosted agent can expose Responses, Invocations, Invocations (WebSocket), Activity and A2A. The protocol decides the payload your container receives and how much session, streaming and background work the platform manages for you.","useIf":"You are choosing how clients, channels or other systems will call a hosted agent.","avoidIf":"The agent is a prompt agent, where the platform picks the protocol for you.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t05","order":5,"group":"Foundry Agent Service","title":"Sessions, sandbox lifecycle and state","summary":"Compute follows the session, not the request. Each session gets a VM-isolated sandbox that moves between Active, Idle and Resumed, with `$HOME` and `/files` persisted across idle periods and deleted after 30 days of inactivity.","useIf":"You are designing where a hosted agent keeps working files, history and checkpoints, and how long they live.","avoidIf":"You run a prompt agent, where the platform owns conversation state and you have no sandbox to manage.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w12-t06","order":6,"group":"Foundry Agent Service","title":"Versions, scaling, networking and identity of hosted agents","summary":"Hosted agent versions are immutable snapshots served one at a time. Scale is per session with billing on allocated CPU and memory, networking supports bring-your-own VNet, and every agent gets its own Entra identity.","useIf":"You are sizing, releasing, isolating or authorizing a hosted agent in production.","avoidIf":"You are still choosing between agent types: read the overview and runtime matrix first.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w12-t07","order":7,"group":"Foundry Agent Service","title":"Responses API direct vs agents","summary":"Calling the Responses API from your own code gives an ephemeral agent: the definition lives in your app, nothing is created in Foundry, yet you still use Foundry models, tools, OBO auth and project governance.","useIf":"The agent already runs in your own process and the definition should ship and version with the application.","avoidIf":"You want Foundry to host, version, publish or give a stable endpoint to the agent.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t08","order":8,"group":"Tools and knowledge","title":"Toolboxes and the managed MCP endpoint","summary":"A toolbox curates tools once and exposes them behind one managed MCP-compatible endpoint with central authentication, guardrails and versioning. Any MCP client can use it, not only Foundry agents.","useIf":"Several agents or runtimes share tools, and you want one credential, governance and release point.","avoidIf":"The tool is not toolbox-eligible or must execute inside your own process.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t09","order":9,"group":"Tools and knowledge","title":"Built-in tools","summary":"Foundry agents act through built-in tools such as file search, code interpreter, web search, Azure AI Search, OpenAPI, SharePoint, Azure Functions and function calling. Each has a different cost, data boundary and toolbox eligibility.","useIf":"You are choosing which tool gives an agent facts, computation or actions, and what each choice costs in data exposure.","avoidIf":"You need permission-aware retrieval across many enterprise sources: look at Foundry IQ knowledge bases first.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t10","order":10,"group":"Tools and knowledge","title":"Foundry IQ knowledge bases","summary":"Foundry IQ is a managed, permission-aware knowledge layer. A knowledge base combines knowledge sources with retrieval settings and runs on Azure AI Search agentic retrieval, so several agents can share one governed source of grounding.","useIf":"Agents need grounded answers from scattered enterprise content with citations and per-user permissions.","avoidIf":"You only need a few ad hoc files in a chat, or one well-tuned index with fixed query logic and a tight latency budget.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t11","order":11,"group":"Tools and knowledge","title":"Connected agents vs A2A tool","summary":"The classic Connected Agents tool is not available in the new Foundry Agent Service. Use the A2A tool for peer agents, Agent Framework orchestration inside hosted code, or Workflows (preview, retiring 2026-12-01).","useIf":"One Foundry agent must delegate to another agent, in or outside Foundry, and you are migrating off Connected Agents.","avoidIf":"The peer is a plain function or API: use a tool. Use A2A only when the peer is a real agent with its own reasoning.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w12-t12","order":12,"group":"Tools and knowledge","title":"Memory in Foundry","summary":"Foundry memory (preview) is managed long-term memory: an LLM extracts facts from conversations, consolidates them into a memory store and retrieves them across sessions, scoped per user.","useIf":"An agent should remember user preferences, past issues or learned routines across sessions.","avoidIf":"The content is shared policy or documents, the project needs VNet integration for memory stores, or preview is not allowed.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t13","order":13,"group":"Publish and operate","title":"Publishing: Teams, Microsoft 365 Copilot and the Entra Agent Registry","summary":"Publishing exposes an agent's stable endpoint to Teams and Microsoft 365 Copilot through an Azure Bot Service resource. Scope decides who can see and call it, and you roll new versions behind the same endpoint.","useIf":"People should reach a Foundry agent from the tools where they already work, with an approval path and version control behind it.","avoidIf":"The agent is called only from your own application (no publish needed) or the data flows into Microsoft 365 and Teams are not approved.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t14","order":14,"group":"Publish and operate","title":"Tracing, evaluation and the agent optimizer","summary":"Foundry traces every agent run into Application Insights using OpenTelemetry conventions. The agent optimizer (limited preview) closes the loop by evaluating an agent against a dataset and proposing better instructions, tool descriptions, skills or models.","useIf":"You need to see why an agent behaved as it did, and turn that evidence into measured improvements.","avoidIf":"You need only a quick prototype with no quality bar, or your policy forbids limited-preview features in the improvement loop.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w12-t15","order":15,"group":"Identity and governance","title":"Entra Agent ID: blueprints, identities and agent users","summary":"Entra Agent ID models an agent as a blueprint that holds credentials, agent identities that carry no credentials, and an optional agent user account. Sponsors and owners give each agent a named accountable human.","useIf":"You need to understand what an agent is in Entra, who owns it, and how credentials and lifecycle are controlled.","avoidIf":"You only call a model from an app and do not yet need a distinct identity for the agent.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w12-t16","order":16,"group":"Identity and governance","title":"Autonomous vs on-behalf-of agents","summary":"An agent can act as itself (app permissions), on behalf of a signed-in user (delegated permissions) or as its own user account. Pick the mode first, then confirm permissions and consent, because the mode decides whose access bounds the data and who is accountable.","useIf":"You are deciding whose permissions an agent uses when it reads data or takes actions.","avoidIf":"The agent touches no protected resources, so identity mode has no effect.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w12-t17","order":17,"group":"Identity and governance","title":"Agent 365: observe, govern, secure","summary":"Microsoft Agent 365 is a control plane that observes, governs and secures the agents in an organization. It is GA since 2026-05-01 for the Commercial segment, licensed per user, and it does not build or host agents.","useIf":"You must see, govern and protect agents from many platforms in one admin surface.","avoidIf":"You expect it to build, host, orchestrate or run an agent: it does none of these.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w12-t18","order":18,"group":"Identity and governance","title":"Agent 365 registry, Purview and Defender","summary":"The Agent 365 registry is the unified inventory of agents. Purview audits, classifies and protects the data they touch, and Defender discovers agents and detects threats. Entra stays the identity layer through Agent ID.","useIf":"You administer or secure agents and need to know what you can see, what is on by default and what needs separate onboarding.","avoidIf":"You only need to build an agent: use the runtime topics first.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w12-t19","order":19,"group":"Identity and governance","title":"Runtime choice matrix","summary":"Choose the agent runtime by control, effort, protocol needs, isolation and where code must run: a Foundry prompt agent, a hosted agent, self-hosting on AKS or Container Apps with registration, or a Copilot Studio agent.","useIf":"You must justify where an agent runs and what each option costs in control, operations and governance.","avoidIf":"The runtime is already fixed by policy and you only need to wire identity or governance.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3}],"quizCount":79,"flashcardCount":66,"refCount":43,"topicCount":19,"scenarioCount":39,"file":"content/w12.js"},{"id":"w13","order":13,"region":"senses","title":"Multimodality","short":"Multimodality","tagline":"The question arrives as a photo, a PDF or a voice.","story":"The question no longer comes as clean text. It arrives as a phone photo of a chart, a scanned manual or a caller who pauses to think. Every modality adds a token bill, a parsing choice and a new way to smuggle in instructions or personal data.","oneLiner":"Price the pixels, pick a reader, index what the page shows, choose a voice architecture and treat every image as untrusted input.","minutes":110,"prereqs":["w03","w05"],"levels":[{"id":"w13-l1","order":1,"title":"Spend pixels wisely","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"A photo, a screenshot or a scanned page reaches the model. Text density, the need for pixel coordinates and the token budget are all open. Choose a detail level and predict the bill before you ship."},{"id":"w13-l2","order":2,"title":"Read the page, watch the clip","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"Pages arrive as scans, forms, slide decks and videos. Layout complexity, volume, the need for grounded fields and where the code may run are all open. Choose how the content gets read."},{"id":"w13-l3","order":3,"title":"Find the figure","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"The answer sits in a chart, a diagram or a layout that text extraction flattens. How much meaning lives in visuals, whether you need text citations and the storage budget are open. Choose how pages and figures become searchable."},{"id":"w13-l4","order":4,"title":"Speak and listen","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"A voice arrives and must be answered before the caller loses patience. Latency, control over the text in between and cost are open. Choose the architecture, the transport and the turn detection."},{"id":"w13-l5","order":5,"title":"Trust the pixels","kind":"problem","minutes":16,"quizCount":3,"hasDefend":false,"brief":"Anything an image says can be an instruction, a leak or a harm. Where you read, redact, shield and moderate, and what people who cannot see the picture receive, are all open."},{"id":"w13-l6","order":6,"title":"Boss: the assistant that reads and listens","kind":"boss","minutes":22,"quizCount":3,"hasDefend":true,"brief":"An interviewer asks for an assistant that reads visually rich documents and takes voice calls, and leaves every dial open. Clarify, compare, pick, name the failures and say how you will measure."}],"topics":[{"id":"w13-t01","order":1,"group":"Foundations","title":"Modalities landscape and choosing a modality","summary":"A modality is a form of data (text, image, audio, video, document) that a model reads or produces. The design question is which representation should carry the evidence for each task.","useIf":"Inputs arrive as photos, scans, calls or clips and you must decide what to keep as pixels or sound and what to turn into text.","avoidIf":"Every input is already clean text. Adding a modality only adds cost, failure modes and safety surface.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w13-t02","order":2,"group":"Vision","title":"Image input: detail levels, token cost and limits","summary":"Images are billed as input tokens. The `detail` setting and the model family decide how the image is resized and counted, so the same photo can cost 85 or 10,000 tokens.","useIf":"You send photos, scans or screenshots to a vision model and must predict cost, TPM load and accuracy.","avoidIf":"A text extraction service already returns what you need, which is cheaper than any image token.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w13-t03","order":3,"group":"Vision","title":"Vision failure modes","summary":"Vision models read images fluently but wrongly in predictable places: counting, spatial positions, small or rotated text, chart details and metadata. Know the list, route around it and test each failure class.","useIf":"You rely on a vision model for answers that people will act on, and you need a plan for the known weak spots.","avoidIf":"The task is coarse description where an occasional miss is harmless. Heavy mitigation would cost more than the error.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w13-t04","order":4,"group":"Audio and voice","title":"Audio input and speech output","summary":"Speech to text and text to speech are separate services with separate modes: live streaming, fast synchronous files and batch. Pick the mode by latency need, volume and the extras you need, such as speaker labels or word timestamps.","useIf":"You turn audio into text for search, captions, analytics or an agent, or you speak a text answer back.","avoidIf":"The user is in a live conversation and you want one model to listen and speak. See the realtime topic instead.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w13-t05","order":5,"group":"Audio and voice","title":"Realtime speech-to-speech","summary":"A realtime speech-to-speech model hears audio, reasons, calls tools and speaks back inside one persistent session. You choose the transport, manage keys and sessions, and pay for audio tokens that grow with the conversation.","useIf":"A person talks to the system live and low latency matters more than inspecting text between stages.","avoidIf":"You must filter, log or rewrite the text before the model sees it, or the audio is recorded and nobody waits.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w13-t06","order":6,"group":"Audio and voice","title":"Cascaded vs speech-to-speech pipelines","summary":"A cascaded (chained) pipeline runs speech-to-text, a text agent and text-to-speech as separate stages. A speech-to-speech model does it in one. The choice trades latency against control over the text in between.","useIf":"You are choosing a voice architecture and must weigh latency, text inspection, tool-heavy backends, cost and platform limits.","avoidIf":"You have a single fixed requirement that already decides it, such as a rule that no text may be stored, or a hard sub-second target.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w13-t07","order":7,"group":"Audio and voice","title":"Voice Live and turn detection","summary":"Voice Live is Azure's managed speech-to-speech service. Turn detection decides when a caller has finished and when to let them interrupt, and it is the setting that most changes how a voice agent feels.","useIf":"You build a voice agent on Azure, or tune when an agent should start and stop talking.","avoidIf":"You need a stage-by-stage pipeline you can inspect, or the whole stack must be GA only, in which case check each Voice Live surface first.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":2},{"id":"w13-t08","order":8,"group":"Video and documents","title":"Video understanding","summary":"Video is frames plus audio plus time. Managed analyzers sample about one frame per second at low resolution and transcribe speech, so fast events and fine on-screen text need your own sampling.","useIf":"You need searchable scenes, summaries or fields from recorded video, and speech plus coarse visuals carry most of the meaning.","avoidIf":"The answer depends on fast motion or tiny on-screen text, unless you control the frame sampling yourself.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w13-t09","order":9,"group":"Video and documents","title":"Document understanding: OCR vs layout vs vision LLM","summary":"Four ways to read a document: layout or OCR only, a Document Intelligence form model, a Content Understanding analyzer, or a vision LLM called directly. They differ in fields, confidence, grounding, cost and where they can run.","useIf":"You turn scans, forms, contracts or reports into text or typed fields and must pick the tool by document shape, evidence need and hosting.","avoidIf":"The document is already clean digital text with no layout that matters. Plain text extraction is enough.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w13-t10","order":10,"group":"Multimodal retrieval","title":"Multimodal embeddings","summary":"A multimodal embedding model puts text and images into one vector space, so a text query can retrieve images and an image can retrieve look-alikes. You get similarity but no explanation or citation text.","useIf":"Users search by example image, or you need look-alike retrieval without an LLM call per image at index time.","avoidIf":"Answers need citable text or reasons. Verbalizing the image into text is the better path.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w13-t11","order":11,"group":"Multimodal retrieval","title":"ColPali and page-image retrieval","summary":"ColPali embeds each page as an image into many vectors and scores queries by late interaction (MaxSim). It skips OCR and chunking and keeps layout and figures, at roughly 30 times the storage of a text vector per page.","useIf":"Pages are visually rich (charts, diagrams, tables, slides), parsing is brittle, and you can pay for a larger index.","avoidIf":"Content is mostly prose, the index budget is tight, or every answer must cite quoted text.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w13-t12","order":12,"group":"Multimodal retrieval","title":"Caption-then-embed vs multimodal embeddings vs page images","summary":"Four ways to make visual content searchable: parse to text, caption figures with an LLM then embed the text, embed images directly into one vector, or embed whole pages as multi-vector images. The right one depends on where meaning lives, how users query and what evidence the answer must carry.","useIf":"You are designing retrieval over documents or images with figures, and must choose the indexing path and how to evaluate it.","avoidIf":"The corpus is plain text with no figures. A normal text index already does the job.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w13-t13","order":13,"group":"Safety","title":"Multimodal safety: image injection, content safety and PII","summary":"Anything an image says can be an instruction, a leak or a harm. No single service covers prompt injection, harmful content, PII and faces, so you layer controls and treat text read from images as untrusted.","useIf":"Users or documents supply images or scans that a model reads, and the system can take actions or handle personal data.","avoidIf":"Images are produced and consumed only by your own trusted pipeline with no tools and no personal data.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":3}],"quizCount":55,"flashcardCount":57,"refCount":30,"topicCount":13,"scenarioCount":29,"file":"content/w13.js"},{"id":"w14","order":14,"region":"senses","title":"Evaluation","short":"Evaluate","tagline":"Prove it works before launch, then keep proving it with live traffic.","story":"The answer came back, and it sounds right. Nobody on the team can say whether it is right, whether the last change made it worse, or whether it will be right tomorrow. This world turns opinions into measurements: golden sets, retrieval and answer metrics, judges you can trust, agent runs you can repeat and gates that block a bad release.","oneLiner":"Measure each stage on its own, calibrate your judges, quantify the noise, and gate releases on evidence.","minutes":120,"prereqs":["w05","w10"],"levels":[{"id":"w14-l1","order":1,"title":"Draw the map before you pick a metric","kind":"concept","minutes":12,"quizCount":3,"hasDefend":false,"brief":"A team asks how it will know the assistant works. The stage, the traffic, the risk and the label budget are all unspecified. Decide which checks run where, when they run and what they are allowed to cost."},{"id":"w14-l2","order":2,"title":"Plant the golden set","kind":"problem","minutes":14,"quizCount":4,"hasDefend":false,"brief":"You have no labelled data and one domain expert with a free afternoon. The stage, the traffic and the drift you can tolerate are unspecified. Decide where cases come from and how you keep them honest."},{"id":"w14-l3","order":3,"title":"Score the retrieval, then the answer","kind":"problem","minutes":20,"quizCount":4,"hasDefend":false,"brief":"A RAG answer is wrong. The labels you hold, the number of chunks an answer needs and the completeness of your judgments are all unspecified. Pick the metrics that say which half broke before you touch the prompt."},{"id":"w14-l4","order":4,"title":"Judge the judge","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"Your scorer is a model, and models have habits. The decision you are making, the availability of reference answers and the cost of a wrong verdict are unspecified. Set up the judge so that a change in score means something."},{"id":"w14-l5","order":5,"title":"Grade the agent, then trust the number","kind":"problem","minutes":20,"quizCount":4,"hasDefend":false,"brief":"An agent can reach the right result by several tool sequences, and it can fail on the second attempt of a task it passed the first time. The side effects of its tools, your need to localize failures and the size of your suite are unspecified. Decide what to grade and how many times to run it."},{"id":"w14-l6","order":6,"title":"Gate it, attack it, watch it","kind":"problem","minutes":20,"quizCount":4,"hasDefend":false,"brief":"A change is ready to ship. The harm if it is worse, the traffic you have and the quality signal you trust are all unspecified. Design the gate that blocks it, the attack that probes it and the live watch that follows it."},{"id":"w14-l7","order":7,"title":"Boss: ship it with evidence","kind":"boss","minutes":18,"quizCount":4,"hasDefend":true,"brief":"An interviewer asks you to build an evaluation strategy for an AI assistant, before launch and after. Every dial is unspecified. Practise the five steps of Dial-and-Defend out loud, then compare with the model answer."}],"topics":[{"id":"w14-t01","order":1,"group":"Foundations","title":"Why LLM evaluation is different","summary":"Classic tests assert one exact output. LLM features vary run to run, accept many valid answers and fail in stacked layers, so evaluation becomes measurement: a dataset, a scorer with known error, repeated trials and a decision rule.","useIf":"You are about to ship or change an LLM feature and must decide how you will know it works.","avoidIf":"The output is fully mechanical (a schema, a lookup, a regex) and a plain unit test already covers it.","minutes":6,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t02","order":2,"group":"Foundations","title":"Offline vs online evaluation","summary":"Offline evaluation runs a fixed dataset with reference answers before release. Online evaluation scores sampled live traffic without references after release. You need both, joined by a loop that turns production failures into new test cases.","useIf":"You must decide which checks gate a release and which keep watching after it.","avoidIf":"You are tempted to use either one alone: offline alone misses drift, online alone lets users find regressions.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t03","order":3,"group":"Foundations","title":"Component vs end-to-end evaluation","summary":"Component evals score one stage with the other stages held fixed, so a fault points at a layer. End-to-end evals score the whole system on the user's task, so they say whether users are affected. Use many cheap component checks and fewer expensive end-to-end ones.","useIf":"A pipeline has several stages (retrieve, rerank, generate, call tools) and you need to know which one broke.","avoidIf":"The system is a single model call with no retrieval or tools, where one end-to-end score is the component.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t04","order":4,"group":"Data","title":"Golden datasets","summary":"A golden dataset is a versioned set of inputs with expected behaviour (reference answers, relevant document ids, tool sequences or a rubric) that every candidate is scored against. Its value comes from who labelled it, how each row was made and whether it stays held out.","useIf":"You need a repeatable yardstick to compare versions of a prompt, retriever, model or agent.","avoidIf":"You treat a public benchmark as your yardstick, or you let the team tune on the same rows it reports on.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t05","order":5,"group":"Data","title":"Synthetic data generation","summary":"A model generates test inputs, and sometimes reference answers, from your documents or your agent's definition. It solves the cold start and widens coverage, but only after human review and with a tag that keeps it apart from real rows.","useIf":"You have no traces yet, expert time is scarce, or you need more edge-case coverage than hand writing allows.","avoidIf":"You plan to use unreviewed generated rows as the only evidence of quality, or to keep them after the prompt changed.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t06","order":6,"group":"Metrics","title":"Retrieval metrics","summary":"Rank metrics score a retriever against labelled relevant documents: precision@k, recall@k, hit rate, MRR and nDCG. Pick by label type and by whether one chunk or several are needed, and tie k to the chunks your prompt really receives.","useIf":"You are choosing or tuning a retriever, reranker or chunking strategy and have, or can build, relevance labels.","avoidIf":"You want to know whether the final answer is good. Retrieval metrics say nothing about generation.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t07","order":7,"group":"Metrics","title":"RAGAS metrics","summary":"RAGAS defines LLM-judged metrics for RAG: faithfulness and answer relevancy for the generator, context precision, context recall and entities recall for the retriever, and noise sensitivity for how irrelevant context corrupts answers. Each has inputs it needs and a blind spot.","useIf":"You need readable RAG metric definitions and have few or no relevance labels.","avoidIf":"You expect a faithfulness score to prove the answer is true, or you compare scores across different judge or embedding models.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t08","order":8,"group":"Metrics","title":"Foundry and Azure AI Evaluation evaluators","summary":"Foundry ships built-in evaluators for quality, RAG, safety and agents, plus custom evaluators, through two SDK paths. Many are preview. Choose by what you can label, which tools your agent calls and whether a preview dependency is acceptable.","useIf":"You build on Foundry or Azure and want portal-visible scores, safety evaluators and CI-friendly runs.","avoidIf":"You need a feature with an SLA today and the evaluator you want is preview, or your agent uses tools the evaluators barely support.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w14-t09","order":9,"group":"Judges","title":"LLM-as-judge setups","summary":"An LLM judge scores outputs against a rubric. The setup, not the model alone, decides reliability: pass/fail with a critique, pairwise with order swapping, reference-guided grading, rubric prompts, or several judges. Pick by the decision you are making and the stakes.","useIf":"Quality is about meaning, tone or completeness that code cannot check, and you can calibrate the judge against human labels.","avoidIf":"A code check or an exact reference comparison already answers the question, or you cannot spare any human labels to validate the judge.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t10","order":10,"group":"Judges","title":"Judge biases and calibration","summary":"LLM judges have measurable habits: they favour the first position, longer text and their own outputs. You defend with order swapping, references, a different judge family and, above all, calibration against labels from one accountable human expert, reported as true positive and true negative rates.","useIf":"A judge score will gate a release or rank candidates, so its errors must be measured and bounded.","avoidIf":"You only need a rough trend and the judge's absolute accuracy does not matter.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w14-t11","order":11,"group":"Agents and safety","title":"Agent trajectory and tool-call evaluation","summary":"An agent run is a trajectory: model steps, tool calls with arguments, tool results and a final answer. Grade the outcome first, then add process checks on tool selection, arguments and output use so a failure points at a step. Rigid expected sequences punish valid alternatives.","useIf":"An agent chooses tools and takes multiple steps, and you need to know both whether it succeeded and where it went wrong.","avoidIf":"The task has many valid paths and you are tempted to demand one exact tool sequence.","minutes":9,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w14-t12","order":12,"group":"Agents and safety","title":"Non-determinism, pass^k and significance","summary":"Run each task several times. Report pass@k when one success is enough and pass^k when every run must succeed. Attach a confidence interval to every pass rate and compare versions paired, because small eval sets cannot see small differences.","useIf":"An agent or prompt change moves a score by a few points and you must decide whether it is real.","avoidIf":"The system is deterministic and fully checkable, where one run is the truth.","minutes":10,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w14-t13","order":13,"group":"Agents and safety","title":"Red teaming and safety evaluation","summary":"Red teaming probes a system with adversarial inputs to find harms and security failures. Start with manual expert probing, then automate with PyRIT and the Foundry AI Red Teaming Agent, score attack success rate, and review results by hand. Scans are non-deterministic and cover only the targets and categories each mode supports.","useIf":"You are about to expose a model or agent to users, tools or untrusted content and must measure how it fails under attack.","avoidIf":"You expect one scan to certify safety, or to run attacks against production systems that have real side effects.","minutes":10,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w14-t14","order":14,"group":"Operating","title":"CI gates and regression testing","summary":"A gate is a rule plus a noise budget. Compare against a baseline with an interval or significance test instead of a fixed threshold, run a small fast suite per pull request and a large one nightly, block on safety and regression suites, and control evaluation cost.","useIf":"Prompts, models, retrievers or tools change often and you need to stop regressions before they ship.","avoidIf":"You gate on one noisy run against a fixed score, or you block merges on capability suites that are meant to start low.","minutes":9,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w14-t15","order":15,"group":"Operating","title":"A/B, shadow, canary and feedback signals","summary":"Online experiments test a new version on live traffic. Shadow traffic hides it from users, a canary exposes a small share, an A/B test randomises users to measure outcomes, and feedback signals feed triage. Pick by harm if the new version is worse, traffic volume and what quality signal exists without references.","useIf":"Offline results look good but only real traffic can show user outcomes, drift or rare failures.","avoidIf":"Harm from the worse version is high and you have no safe exposure path, or traffic is too low to detect the effect you care about.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":3}],"quizCount":72,"flashcardCount":76,"refCount":58,"topicCount":15,"scenarioCount":32,"file":"content/w14.js"},{"id":"w15","order":15,"region":"senses","title":"Observability","short":"Observability","tagline":"Make a wrong answer explain itself without leaking the data behind it.","story":"The answer was wrong and nobody can say why. A classic service fails with an error, but an LLM system returns a fluent 200 that happens to be false, spread across model calls, tools and several agents. This world teaches you to record enough to explain a run, keep customer text out of the places it should not be, and meter cost and quality without drowning in data.","oneLiner":"Record the shape of every run by default, keep content behind an explicit policy, and alert on metrics because metrics are not sampled.","minutes":100,"prereqs":["w09","w11"],"levels":[{"id":"w15-l1","order":1,"title":"Name the span: what one wrong answer should leave behind","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"An answer was wrong and nobody can say why. Decide what each model call, tool call and agent run must record so that one trace explains it, and how much to trust the standard that names those records. The dials are not given."},{"id":"w15-l2","order":2,"title":"Decide what the trace may hold: the content capture board","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"Debuggers want the full prompt and the tool result. Privacy and retention rules want none of it in the trace. Decide what spans carry, where content lives, who can read it, and which switch controls which layer. The dials are not given."},{"id":"w15-l3","order":3,"title":"Follow the trace across hops, and keep the volume down","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"A request crosses a gateway, an agent, an MCP server and a peer agent. Some hops split the trace, and the bill for traces keeps growing. Decide how context travels, where it breaks, and what you sample. The dials are not given."},{"id":"w15-l4","order":4,"title":"Meter the tokens, set the targets, pick the backend","kind":"problem","minutes":22,"quizCount":3,"hasDefend":false,"brief":"Finance wants cost per team, the on-call engineer wants a target that tells her when to wake up, and the product owner wants to know whether answers got worse. Choose the meters, the SLIs and the place the telemetry lives. The dials are not given."},{"id":"w15-l5","order":5,"title":"Boss: make the crew debuggable without leaking data","kind":"boss","minutes":25,"quizCount":4,"hasDefend":true,"brief":"An interviewer describes a multi-agent system that nobody can debug, with a compliance rule against customer text in logs. The dials are not given. Clarify them, compare the options, choose, and say what would flip your answer."}],"topics":[{"id":"w15-t01","order":1,"group":"Foundations","title":"What to observe in LLM systems","summary":"LLM systems fail quietly: the request succeeds, the text is fluent and the content is wrong. Observability records the shape of every run (spans, tokens, finish reasons, tool calls) and treats content as a separate, governed decision.","useIf":"You operate, or are about to operate, a model-backed feature and need to explain wrong answers, slow runs and surprising bills.","avoidIf":"You expect status codes and error rates alone to tell you whether the system works.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w15-t02","order":2,"group":"Standards","title":"OTel GenAI semantic conventions","summary":"The OpenTelemetry GenAI semantic conventions define shared span names, attributes and metrics for model calls, agents, tools, workflows and MCP, so any instrumented app can feed any compatible backend. All of it has status Development.","useIf":"You instrument LLM or agent code and want dashboards, alerts and backends that survive a change of framework or vendor.","avoidIf":"You treat attribute and metric names as frozen: they are still changing and moved repositories on 2026-05-05.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w15-t03","order":3,"group":"Standards","title":"Spans for chat, agent and tool calls","summary":"An agent run becomes a tree of spans: invoke_agent at the top, a chat span for each model call and an execute_tool span for each tool call, optionally under an invoke_workflow span. The nesting shows where time and tokens went.","useIf":"You need to see which model calls, tool calls and sub-agents made up one agent run and how long each took.","avoidIf":"You only need aggregate rates: metrics are cheaper and unsampled for that.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w15-t04","order":4,"group":"Standards","title":"Metrics: tokens, duration and cost","summary":"Metrics are unsampled aggregates. Use token usage counters for totals and cost, duration histograms for latency and agent metrics for loops, and keep dimensions low-cardinality so attribution does not break the backend.","useIf":"You need trustworthy totals for tokens, latency and cost, dashboards and alerts that sampling must not distort.","avoidIf":"You compute totals from sampled spans or per-operation histograms: both give wrong numbers.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w15-t05","order":5,"group":"Distributed tracing","title":"Trace propagation across services","summary":"One user request crosses agents, MCP servers, A2A peers and queues. Propagating W3C trace context over each hop, in HTTP headers or MCP params._meta, keeps it one trace. Some hops need correlation ids instead.","useIf":"A single request touches several processes and you want one trace, not five unrelated ones.","avoidIf":"You forward baggage or trace context to parties that should not see it, or assume every framework propagates it for you.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w15-t06","order":6,"group":"Privacy and volume","title":"Content capture, redaction and privacy","summary":"Prompts, outputs and tool payloads are the best debugging evidence and the riskiest telemetry. The GenAI conventions make content capture opt-in, and production setups usually keep it off spans, in a governed store, referenced from the trace.","useIf":"You decide whether and how telemetry may hold prompts, retrieved text and tool results.","avoidIf":"You flip one global content flag in production without redaction, retention and access rules.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w15-t07","order":7,"group":"Privacy and volume","title":"Sampling and retention","summary":"Agent traces are large, so most systems keep only a share. Head sampling decides at the start of a trace, tail sampling decides after seeing it, and metrics are never sampled. Retention tiers then set how long what you kept stays searchable.","useIf":"Trace volume or cost is climbing and you must decide what to keep, for how long and where totals will come from.","avoidIf":"You compute token totals from sampled traces or sample so hard that the failing runs vanish.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w15-t08","order":8,"group":"Platforms","title":"Foundry tracing and Application Insights","summary":"Foundry can collect traces for its agents server-side after you connect an Application Insights resource to the project, with no code change. Client-side tracing and the Agents view add depth, and KQL over the dependencies table answers custom questions.","useIf":"Your agents run in Foundry Agent Service, or you want one Application Insights resource to hold traces from Foundry and your own code.","avoidIf":"You assume server-side tracing covers every agent type, or that Foundry traces and Agent Framework telemetry are the same pipeline.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":2},{"id":"w15-t09","order":9,"group":"Platforms","title":"Agent Framework built-in telemetry","summary":"Agent Framework emits OpenTelemetry spans and metrics for agent runs, model calls and tool calls. You supply the exporter. Python instrumentation is on by default since python-1.6.0, .NET needs a wrapper, and sensitive content stays off unless you enable it.","useIf":"You build agents or workflows with Agent Framework and want traces and metrics in any OpenTelemetry backend.","avoidIf":"You assume telemetry flows by default: spans are created, but no exporter is installed automatically.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w15-t10","order":10,"group":"Operating","title":"Dashboards, SLIs, SLOs and alerts","summary":"Turn telemetry into targets: pick a few SLIs that reflect what users feel (availability, time to first output, tool reliability, runaway runs, cost, quality), set SLOs from your own baseline and page on error-budget burn rate instead of raw thresholds.","useIf":"You must define what healthy means for an LLM or agent service, and when to wake someone up.","avoidIf":"You copy someone else's numbers or alert on every dip in a noisy quality score.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w15-t11","order":11,"group":"Operating","title":"Online quality monitoring","summary":"Online quality monitoring scores a sample of live traces with reference-free evaluators, such as LLM judges and safety checks, then tracks the scores for drift. Sampling rate, filters and judge cost are the controls, and privacy rules apply to what judges read.","useIf":"Quality failures are silent, production inputs differ from your test set, and you need an early signal between releases.","avoidIf":"You score all traffic with an untested judge, or send regulated content to an evaluator you do not control.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w15-t12","order":12,"group":"Operating","title":"Tooling landscape","summary":"Because the GenAI conventions ride on OpenTelemetry, one instrumented app can feed Application Insights, Langfuse, LangSmith, Phoenix or a local dashboard. Pick the backend by ecosystem, the features you need around traces and where your data may live.","useIf":"You must choose, combine or replace a tracing and evaluation backend for LLM applications.","avoidIf":"You pick a tool for its demo and discover later that its transport, data residency or pricing does not fit.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3}],"quizCount":50,"flashcardCount":56,"refCount":30,"topicCount":12,"scenarioCount":25,"file":"content/w15.js"},{"id":"w16","order":16,"region":"operate","title":"Cost, Scale and Reliability","short":"Cost and reliability","tagline":"The bill and the outage arrive together. Plan for both.","story":"The assistant works, so traffic grows, and two things arrive on the same day: a finance review of the token bill and a 429 storm that nobody planned for. Cost, capacity and reliability pull on each other. Caching and routing cut spend, quotas shape what you can send, and every retry or failover has a price in tokens, latency or stale state.","oneLiner":"Find where the tokens go, buy capacity that fits the traffic shape, and fail in ways you chose in advance.","minutes":105,"prereqs":["w02"],"levels":[{"id":"w16-l1","order":1,"title":"Follow the tokens","kind":"concept","minutes":15,"quizCount":3,"hasDefend":false,"brief":"Finance says the model bill doubled while traffic grew 20 percent. Before you cut anything, find where the tokens go and which lever fits. Prices, model mix, prompt shapes and the amount of agent looping are all unknown."},{"id":"w16-l2","order":2,"title":"Decode the 429","kind":"problem","minutes":20,"quizCount":4,"hasDefend":false,"brief":"Requests start failing with 429 while dashboards show spare quota. Which kind of limit you hit, how the provider counts tokens and where you enforce limits for many consumers are all open."},{"id":"w16-l3","order":3,"title":"Buy capacity that fits the traffic","kind":"problem","minutes":20,"quizCount":4,"hasDefend":false,"brief":"You need model capacity and the invoice must make sense. Traffic may be steady or spiky, users may be waiting or not, and data may or may not be allowed to leave a region. Choose how to buy tokens, then size it."},{"id":"w16-l4","order":4,"title":"Fail well: retries, breakers, hedges and failover","kind":"problem","minutes":25,"quizCount":3,"hasDefend":false,"brief":"Calls to the model fail in different ways: a blip, an exhausted quota, a slow tail, a dead region. Each deserves a different response, and the wrong one makes things worse. How critical the call is, whether it is cheap to repeat and how long recovery may take are all open."},{"id":"w16-l5","order":5,"title":"Boss: stay in budget through a regional incident","kind":"boss","minutes":25,"quizCount":4,"hasDefend":true,"brief":"An interviewer says token spend doubled last quarter, and last week a regional incident took the assistant offline for 40 minutes. Keep it inside budget and available. Traffic shape, latency needs, residency and recovery targets are all unspecified."}],"topics":[{"id":"w16-t01","order":1,"group":"Cost","title":"Where the money goes: token economics","summary":"A model bill is the sum of uncached input, cached input, cache writes, output and reasoning tokens, multiplied by the number of calls a task makes. Knowing which sink dominates tells you which lever to pull.","useIf":"The bill grew faster than traffic, or you must price a new feature before you build it.","avoidIf":"You treat it as a one-number exercise: cost per token alone hides retries, loops and failed tasks.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w16-t02","order":2,"group":"Cost","title":"Cost levers","summary":"Six levers cut spend: trim the prompt, cache the stable prefix, cap output, choose a cheaper model, move work to batch tiers, and reuse whole answers. Each has a break-even and a catch.","useIf":"You know which token sink dominates and must pick the lever that fits it.","avoidIf":"You have not attributed spend yet, or you would trade answer quality you have not measured.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w16-t03","order":3,"group":"Cost","title":"Routing and cascades as a cost lever","summary":"A router picks a model per request, and a cascade tries a cheap model first and escalates when a check fails. Both save money only when query difficulty varies and quality is measured.","useIf":"Most queries are easy, a few are hard, and you have an eval set that can tell them apart.","avoidIf":"Tasks are uniformly hard, no eval set exists, or the prompt cache is your main saving.","minutes":8,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w16-t04","order":4,"group":"Capacity","title":"Quotas, TPM, RPM and 429s","summary":"Providers limit tokens per minute and requests per minute. A 429 has more than one cause, and each provider counts tokens differently, so read the headers before you raise anything.","useIf":"Requests fail with 429 while dashboards show spare quota, or many consumers share one deployment.","avoidIf":"You plan to fix every 429 by asking for more quota or by retrying harder.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w16-t05","order":5,"group":"Capacity","title":"Deployment types and capacity: PAYG, global, data zone, PTU","summary":"Azure sells model capacity as pay-as-you-go Global, Data Zone or regional Standard, as Priority processing, and as provisioned throughput (PTU). The choice follows traffic shape, residency and how tightly latency must hold.","useIf":"You must pick how to buy tokens for a production workload and defend the choice with numbers.","avoidIf":"Traffic is unknown. Start on Global Standard, measure, then size commitments.","minutes":9,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w16-t06","order":6,"group":"Capacity","title":"Batch, flex and async","summary":"Batch and Flex processing trade time for a 50% lower price. Batch queues a file for a 24-hour target, and Flex keeps a synchronous API shape but can be preempted.","useIf":"Nobody waits for the result: evaluations, enrichment, embeddings, classification, backfills.","avoidIf":"A user is waiting, or you cannot tolerate 429, 408 or a result hours later.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w16-t07","order":7,"group":"Gateway and resilience","title":"API Management AI gateway","summary":"An AI gateway in API Management puts token limits, token metrics, semantic caching, content safety, load balancing and a circuit breaker in front of your model deployments, so every team gets one governed endpoint.","useIf":"Several apps or teams share model capacity and you need per-consumer limits, cost attribution and failover in one place.","avoidIf":"One app calls one deployment and the gateway would be a new single point of failure with no policy to enforce.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w16-t08","order":8,"group":"Gateway and resilience","title":"Retries, timeouts and jitter","summary":"A retry spends more of the server's capacity to raise your odds of success. Done once, with backoff, jitter, a cap and a deadline, it absorbs blips. Done at every layer, it turns a blip into an outage.","useIf":"Calls fail transiently with 429, 408 or 5xx, and you must decide what to retry, how long to wait and when to stop.","avoidIf":"The error is a quota or billing failure, a client error, or a side-effecting call with no idempotency key.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w16-t09","order":9,"group":"Gateway and resilience","title":"Circuit breakers, bulkheads and hedging","summary":"A circuit breaker stops calls to a failing dependency, a bulkhead stops one consumer from sinking the rest, and hedging sends an early duplicate to cut tail latency. Each trades capacity, cost or complexity for isolation or speed.","useIf":"A failing or slow dependency, or one noisy consumer, can drag down everything else.","avoidIf":"Traffic is small and failures are rare: simple retries and good timeouts are enough.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w16-t10","order":10,"group":"Gateway and resilience","title":"Fallbacks and graceful degradation","summary":"When the best path fails or capacity runs out, step down a defined ladder: another deployment, a smaller model, fewer features, a cached or retrieval-only answer, then an honest error. Decide the rungs and what you tell users before the incident.","useIf":"A failing model, quota or region must not mean a dead product.","avoidIf":"A degraded answer would be wrong enough to harm users, in which case an honest refusal is the better rung.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w16-t11","order":11,"group":"Gateway and resilience","title":"Regional failover and capacity planning","summary":"Foundry does not fail over for you. You pick a recovery tier, build the second region, size both for the load they must carry, set SLOs with an error budget, and rehearse the switch.","useIf":"A regional incident would break your availability target, or a launch will multiply traffic.","avoidIf":"Your availability target is low enough that a documented hot/cold recovery meets it.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":3}],"quizCount":51,"flashcardCount":54,"refCount":38,"topicCount":11,"scenarioCount":29,"file":"content/w16.js"},{"id":"w17","order":17,"region":"operate","title":"Governance and Human Oversight","short":"Govern agents","tagline":"Someone must be accountable, and the record must show it.","story":"The agent has acted. A customer, an auditor or a regulator will ask who allowed it, who could have stopped it and how you found out. Here you decide how much human oversight each action deserves, which dated rules and frameworks apply, how a fleet of agents is inventoried and retired, and what you do when something goes wrong.","oneLiner":"Match oversight to action risk and reversibility, then prove it with owners, records and a rehearsed incident process.","minutes":120,"prereqs":["w07","w12"],"levels":[{"id":"w17-l1","order":1,"title":"Who holds the brake?","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"An agent is about to act. Decide whether a person approves first, is pulled in on a trigger, reviews a sample afterwards or only sees a log, while reversibility, reach, volume and regulatory class are still open."},{"id":"w17-l2","order":2,"title":"Read the calendar, not the blog post","kind":"problem","minutes":18,"quizCount":4,"hasDefend":false,"brief":"A customer asks which AI rules apply to your assistant and from when. Date every obligation, name your role as provider or deployer, and check that the date on your slide is not one that moved on 2026-07-27."},{"id":"w17-l3","order":3,"title":"Law, guidance, standard or rulebook?","kind":"problem","minutes":18,"quizCount":3,"hasDefend":false,"brief":"A customer asks for ISO 42001, a regulator for EU AI Act evidence and the board for NIST alignment. Decide which framework you adopt first, say what each one is and is not, and decide what you will not claim."},{"id":"w17-l4","order":4,"title":"A fleet needs a lifecycle","kind":"problem","minutes":22,"quizCount":3,"hasDefend":false,"brief":"Agents multiply faster than reviews. Decide how every agent is inventoried, identified, permissioned, reviewed and retired, and which control plane holds the list, while the runtimes, clouds and licences behind your agents are still open."},{"id":"w17-l5","order":5,"title":"When it goes wrong, and what you can show","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"An agent did something it should not, or a regulator asks what the system did last Tuesday. Decide how you detect, contain and classify AI incidents, what you record and what you disclose, before the day it happens."},{"id":"w17-l6","order":6,"title":"Boss: govern the fleet","kind":"boss","minutes":22,"quizCount":3,"hasDefend":true,"brief":"An interviewer asks you to set up governance for a fleet of agents, with every dial unspecified. Practise the five steps of Dial-and-Defend: clarify, list options, pick and flip, name failures, name metrics and rollout."}],"topics":[{"id":"w17-t01","order":1,"group":"Oversight","title":"Human oversight models","summary":"Human oversight ranges from approving each action before it happens, through supervising with a stop control, to setting policy and reviewing samples afterwards. The right level follows the action's reversibility, reach and regulatory class, and costs friction.","useIf":"You must decide how much a person should be involved in what an AI system or agent does.","avoidIf":"You plan to bolt on a yes/no button and call it oversight: approval without evidence or authority is theatre.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w17-t02","order":2,"group":"Oversight","title":"Approval gates and escalation","summary":"An approval gate pauses an agent action until a person decides. Tier actions by reversibility and reach, gate the risky tiers, define who reviews and what happens on timeout, and bind each approval to the request it answers.","useIf":"An agent can take actions with external, irreversible or high-value effects.","avoidIf":"Every tool call would need approval: reviewers will rubber-stamp, so tier the actions first.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w17-t03","order":3,"group":"Oversight","title":"Audit logging and accountability","summary":"An audit log answers who did what, on whose authority, with which evidence and which versions. Log identifiers and decisions by default, keep content on a short, controlled leash, and make the accountability chain explicit.","useIf":"You must reconstruct an agent's action, show a regulator what the system did, or assign accountability after an incident.","avoidIf":"You plan to dump full prompts into a general log store: it copies protected content into a place with weaker access control.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w17-t04","order":4,"group":"Regulation and standards","title":"EU AI Act","summary":"The EU AI Act sorts AI systems by risk and assigns duties to providers and deployers on a dated timetable. The 2026 Omnibus moved the high-risk dates, while transparency and general-purpose AI enforcement began on 2026-08-02.","useIf":"You build or deploy AI for people in the EU and must say which obligations apply to you and from when.","avoidIf":"You treat a blog post date as final or this page as legal advice: confirm legal text with counsel.","minutes":10,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w17-t05","order":5,"group":"Regulation and standards","title":"NIST AI RMF and the GenAI profile","summary":"The NIST AI Risk Management Framework is voluntary guidance with four functions: Govern, Map, Measure and Manage. NIST AI 600-1 adds a Generative AI Profile with twelve risks. It gives a shared vocabulary, not a certificate.","useIf":"A customer, board or team needs a common way to describe AI risk work, especially for generative AI.","avoidIf":"You need a legal compliance statement or a certifiable standard: this is neither.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w17-t06","order":6,"group":"Regulation and standards","title":"ISO/IEC 42001 and the Microsoft Responsible AI Standard","summary":"ISO/IEC 42001 is a certifiable management system standard for how an organization governs AI. Microsoft's Responsible AI Standard is an internal rulebook that Microsoft released externally. Neither certifies one chatbot.","useIf":"A customer asks for a certificate, or you are designing an internal AI governance rulebook.","avoidIf":"You want to certify a single application's behaviour or prove EU AI Act compliance with a certificate alone.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w17-t07","order":7,"group":"Operating governance","title":"Agent governance lifecycle","summary":"Govern a fleet of agents through five stages: inventory, identity, permissions, review and retirement. Every agent needs a sponsor, an identity with limited access, periodic review and a full shutdown path.","useIf":"Agents are multiplying across teams and nobody can list them, say who owns them or revoke their access quickly.","avoidIf":"You have one agent in a pilot: a simple owner, a ticket and a retirement date may be enough.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w17-t08","order":8,"group":"Operating governance","title":"Documentation and transparency","summary":"Transparency has three audiences: builders who consume model documentation, regulators who ask for technical records, and users who must be told they face an AI or AI-made content. Write a versioned system card and design the user disclosure.","useIf":"You ship an AI system and must explain what it is for, how it was evaluated and what users are told.","avoidIf":"You plan one static document for every audience: a regulator file, an engineer's card and a user notice answer different questions.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w17-t09","order":9,"group":"Operating governance","title":"AI incident response","summary":"AI incidents are probabilistic, context-dependent and hard to root-cause. Extend classic incident response with AI harm categories, domain-weighted severity, AI-specific telemetry, staged remediation and a reporting plan, and rehearse it before you need it.","useIf":"An AI system or agent can cause harm, leak data or act wrongly, and you must contain it and, for some systems, report it.","avoidIf":"You assume your classic security playbook covers it: taxonomy, severity, root cause and telemetry all differ.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":3}],"quizCount":46,"flashcardCount":45,"refCount":37,"topicCount":9,"scenarioCount":25,"file":"content/w17.js"},{"id":"w18","order":18,"region":"operate","title":"Field Notes","short":"Field notes","tagline":"The odd corners that decide interviews.","story":"Past the main journey sit the corners where a senior answer parts from a junior one: how much to let a model think, who may give it orders, where it runs, what it may touch, and what you check first in a system you did not build. Each corner hides one precise detail that turns a general answer into a credible one.","oneLiner":"Learn the odd corners well enough to say one verified detail, one failure and one flip condition about each.","minutes":145,"prereqs":["w01","w10"],"levels":[{"id":"w18-l1","order":1,"title":"Spend thinking where it pays","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"A model can think before it answers, and every thinking token costs time and money. Task difficulty, latency budget, whether answers can be checked and call volume are all open. Decide when a reasoning model beats a standard one and how much effort to give it."},{"id":"w18-l2","order":2,"title":"Prompts are production code","kind":"problem","minutes":22,"quizCount":3,"hasDefend":false,"brief":"A prompt change can break a live system as surely as a code change, and text from tools and documents keeps trying to give the model orders. The release cadence, the number of prompts and the availability of a metric are open. Decide who gets authority, how changes ship and whether an optimizer is justified."},{"id":"w18-l3","order":3,"title":"Rent, host or carry the model","kind":"problem","minutes":24,"quizCount":4,"hasDefend":false,"brief":"The model has to run somewhere, and a customer, regulator or security team will ask where prompts go and who holds the keys. Data control, traffic shape, GPU skills and the quality you need are open. Compare the places a model can run and map each data control to what it really covers."},{"id":"w18-l4","order":4,"title":"Models that act: SQL, sandboxes and screens","kind":"problem","minutes":24,"quizCount":4,"hasDefend":false,"brief":"The model is about to run a query, execute code or click through an interface on someone's behalf. Schema size, whether an API exists, tenant isolation and network needs are open. Choose what runs where, and assume everything the model produces or reads is untrusted."},{"id":"w18-l5","order":5,"title":"Research agents and the wire to the screen","kind":"problem","minutes":20,"quizCount":3,"hasDefend":false,"brief":"A product team wants an agent that researches for minutes, then shows progress and asks for approval in the user's interface. Source control, data boundary, cost and platform churn are open. Decide how to build the research agent and how its events reach the UI."},{"id":"w18-l6","order":6,"title":"Quirks that bite: tokens and made-up facts","kind":"concept","minutes":16,"quizCount":3,"hasDefend":false,"brief":"Two details sit under many production surprises: the same text costs different amounts in different languages, and models state false things fluently. Know the numbers, the taxonomy and the controls well enough to say them in one breath."},{"id":"w18-l7","order":7,"title":"Boss: the first five checks","kind":"boss","minutes":25,"quizCount":4,"hasDefend":true,"brief":"You have inherited an AI system you have never seen. The interviewer asks what you check first. The trigger, the risk tier and your access are not given, so clarify them, order your checks by them and say what would reorder them."}],"topics":[{"id":"w18-t01","order":1,"group":"Models","title":"Reasoning models and test-time compute","summary":"A reasoning model spends extra hidden tokens thinking before it answers, and a per-request effort setting decides how many. More thinking costs time and money and only helps when the task is hard enough to use it.","useIf":"The task needs multi-step planning, debugging or analysis and you can measure whether more thinking improves the result.","avoidIf":"The task is lookup, classification, extraction or voice, where latency and output-token cost matter more than depth.","minutes":8,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w18-t02","order":2,"group":"Models","title":"Instruction hierarchy","summary":"An authority order for instructions: platform and developer rules outrank the user, and text that arrives through tools, documents or images has no authority at all unless a higher level delegates it.","useIf":"Your app mixes developer rules, user input and retrieved or tool text, and you must decide which instructions the model should obey.","avoidIf":"You treat it as a security boundary. It is a training-time mitigation, so you still need isolation, least privilege and confirmations.","minutes":7,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w18-t03","order":3,"group":"Operating prompts","title":"Prompt versioning and LLMOps","summary":"Treat the prompt, model version, parameters, tools and retrieval settings as one release unit: version it, gate it on evals, canary it and keep a pinned bundle to roll back to.","useIf":"A prompt or model change can reach real users and you need to know which combination produced which behaviour.","avoidIf":"You are prototyping with a single user. Heavy release machinery before a golden set exists only slows you down.","minutes":8,"difficulty":"core","scenarioCount":2,"quizCount":3},{"id":"w18-t04","order":4,"group":"Operating prompts","title":"Prompt optimization","summary":"Optimizers search for better instructions, examples, tool descriptions or models against a metric on a dataset, so you re-tune programmatically instead of editing prompt strings by hand.","useIf":"You have a trustworthy metric, a few dozen labelled cases and prompts or models that change often.","avoidIf":"You have no metric or no review capacity. Without a metric there is nothing to optimize, and optimized prompts can regress on specific inputs.","minutes":7,"difficulty":"advanced","scenarioCount":2,"quizCount":3},{"id":"w18-t05","order":5,"group":"Deployment","title":"Serving open models","summary":"Running open-weight models yourself with a serving engine (vLLM, SGLang), a local runtime (Ollama, Foundry Local) or Kubernetes (KAITO on AKS), and knowing when a managed deployment is the better answer.","useIf":"You need custom or open weights, steady high volume, offline use, or control that managed deployments cannot give.","avoidIf":"Residency is the only driver and a data zone or regional deployment meets it, or you lack GPU operations skill and steady load.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w18-t06","order":6,"group":"Deployment","title":"Data residency, ZDR, keys and private endpoints","summary":"Four different controls that people mix up: where inference runs (residency), whether content is retained (ZDR and abuse monitoring), who holds the encryption key (customer-managed keys) and how traffic reaches the service (private networking).","useIf":"A regulator, customer contract or data classification limits where prompts go, how long they persist, who can decrypt them or which network they cross.","avoidIf":"You assume one control covers the others. Each answers a different question and each can disable features.","minutes":9,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w18-t07","order":7,"group":"Specialised agents","title":"Text-to-SQL","summary":"A model turns a natural-language question into SQL. It works on small clean schemas and degrades on large, dirty enterprise ones, and its output must be treated as untrusted input to your database.","useIf":"Users ask ad hoc questions over structured data, the schema can be curated, and wrong answers are cheap to catch or the data is low risk.","avoidIf":"Answers must be exact every time, or the database holds data users must never see and the connection is not locked down.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w18-t08","order":8,"group":"Specialised agents","title":"Code interpreter and sandboxes","summary":"The model writes code and a sandbox runs it, so the agent can calculate, analyse files and draw charts. The code is untrusted, so isolation, per-user sessions and egress limits matter more than the model.","useIf":"The task needs exact calculation, file or data analysis, or chart generation, and you can run model-written code in an isolated environment.","avoidIf":"A plain API or MCP tool already does the job, or you would run the code in the same process or container as your secrets.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w18-t09","order":9,"group":"Specialised agents","title":"Computer-use and browser agents","summary":"A model looks at screenshots and drives a browser or desktop by clicking and typing, or by writing automation code. It reaches software with no API, and it reads untrusted screen content while holding the controls.","useIf":"A task lives behind a user interface that has no API or MCP tool, and you can run the agent in an isolated environment with confirmations.","avoidIf":"An API, MCP tool or script already does the job, or the environment holds sensitive data or logged-in sessions the agent should not reach.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w18-t10","order":10,"group":"Specialised agents","title":"Deep research agents","summary":"A long-horizon agent plans, searches many sources in parallel, reads them and writes a cited report. It can take tens of minutes and many times the tokens of a chat, so value per task and verification decide whether it pays.","useIf":"The question is open-ended and breadth-first, the report is worth real money or time, and you can check citations.","avoidIf":"A single retrieval-augmented answer is enough, latency must be seconds, or no one will verify the sources.","minutes":8,"difficulty":"advanced","scenarioCount":3,"quizCount":3},{"id":"w18-t11","order":11,"group":"Specialised agents","title":"AG-UI","summary":"AG-UI is an open, event-based protocol between a user-facing app and an agent backend. It streams text, tool calls, state and human-in-the-loop pauses so any frontend can work with any agent runtime.","useIf":"You need a rich agent UI (streaming, tool rendering, shared state, approvals) and want a frontend that is not tied to one agent framework.","avoidIf":"You only stream plain chat text from one backend to one frontend and a provider's streaming API already covers it.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w18-t12","order":12,"group":"Pitfalls","title":"Tokenization pitfalls","summary":"Models read tokens, not characters or words. Token counts differ by language, by how numbers are split, by formatting and by tokenizer, and that changes cost, latency, effective context and some answers.","useIf":"You budget cost or context, serve several languages, handle numbers, or are surprised by a bill or a truncation.","avoidIf":"You estimate tokens as characters divided by four and never measure. That rule hides the big differences.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w18-t13","order":13,"group":"Pitfalls","title":"Hallucination taxonomy","summary":"Hallucination is not one bug. Splitting it into factuality versus faithfulness, and intrinsic versus extrinsic, tells you which control to apply and how to detect it.","useIf":"You must diagnose a wrong answer, choose mitigations, or design evals that separate unsupported claims from false ones.","avoidIf":"You treat it as one defect to patch with a prompt line such as 'do not make things up'.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":3},{"id":"w18-t14","order":14,"group":"Pitfalls","title":"Answer craft for architecture interviews","summary":"How to structure, time-box and word an architecture answer so an interviewer can follow it and test it: clarify dials, start from the boring baseline, speak in trade-offs and avoid the common traps.","useIf":"You face a design or architecture question with unspecified constraints and a clock, in an interview or a design review.","avoidIf":"You treat it as a script to recite. The structure serves the content, and a rehearsed answer that ignores the dials fails.","minutes":7,"difficulty":"core","scenarioCount":3,"quizCount":3}],"quizCount":66,"flashcardCount":68,"refCount":58,"topicCount":14,"scenarioCount":39,"file":"content/w18.js"},{"id":"w19","order":19,"region":"finale","title":"Boss Rounds","short":"Boss rounds","tagline":"The interviewer moves the dials. Defend your answer anyway.","story":"The question has crossed every stop on the journey, and the interviewer starts changing the constraints halfway through your answer. Each boss round mixes chapters: a retrieval design that must survive an access review, an assistant that must be fast, cheap and available at once, and an agent platform where tools, peers and workflows share one set of rules. You are scored on clarifying first, choosing for stated dials, naming what flips the choice, and saying how you would know it works.","oneLiner":"Six mixed rounds where every answer crosses chapters, so you practise choosing, flipping and defending under changing constraints.","minutes":150,"prereqs":["w00","w01","w02","w03","w04","w05","w06","w07","w08","w09","w10","w11","w12","w13","w14","w15","w16","w17","w18"],"levels":[{"id":"w19-l1","order":1,"title":"Boss: RAG end to end, from ingest to a cited answer under access control","kind":"boss","minutes":30,"quizCount":6,"hasDefend":true,"brief":"An interviewer hands you a mixed document estate and asks for an assistant that answers with citations and respects each person's access, with every dial unspecified. Carry one design from ingest to cited answer and defend what each stage promises the next one."},{"id":"w19-l2","order":2,"title":"Boss: fast, cheap and available, from latency to caching, cost and resilience","kind":"boss","minutes":28,"quizCount":6,"hasDefend":true,"brief":"An assistant has grown from a pilot to thousands of daily users. Leadership wants it to feel instant, cost less and survive a regional incident without breaking correctness or tenant isolation. Decide which lever fixes which problem and what each lever costs the others."},{"id":"w19-l3","order":3,"title":"Boss: the agent platform, tools, MCP, A2A, patterns and Agent Framework","kind":"boss","minutes":30,"quizCount":6,"hasDefend":true,"brief":"Three teams want agents: one needs internal tools, one must hand work to a vendor's agent, and one runs an approval process that lasts days. Design the platform that connects them, with tools, peers, patterns and runtime, and every dial unspecified."},{"id":"w19-l4","order":4,"title":"Shipping to the enterprise: Foundry hosted agents, identity, Agent 365 and governance","kind":"boss","minutes":25,"quizCount":6,"hasDefend":true,"brief":"An interviewer hands you a framework-built crew, some Copilot Studio agents and a partner agent, and asks for one governed path to production. Every dial is open: ask, compare, choose, name the failures and say how you will prove it is safe to widen."},{"id":"w19-l5","order":5,"title":"Trust under pressure: guardrails, a leak, evaluation and observability","kind":"boss","minutes":25,"quizCount":6,"hasDefend":true,"brief":"A regulated assistant is live with guardrails, an evaluation gate and tracing, and a user reports a snippet from a document they cannot open. Contain it, find the path, prove the fix and keep your traces from becoming a second leak."},{"id":"w19-l6","order":6,"title":"Beyond text: multimodal, reasoning and open-model choices","kind":"boss","minutes":25,"quizCount":6,"hasDefend":true,"brief":"An interviewer wants an assistant that sees photos, reads visually rich pages and talks, and the team is split between a hosted reasoning model and an open model it serves itself. Leave the dials open, then decide the modality path, the model home and the safety stance."},{"id":"w19-l7","order":7,"title":"Rapid fire and the final checklist","kind":"concept","minutes":35,"quizCount":24,"hasDefend":false,"brief":"Twenty-four questions, one or more per chapter, then the ten questions to ask about any AI system you have never seen and the five-step method that turns the answers into a defended design. Run the quiz against a timer, then keep the table as your map."}],"topics":[],"quizCount":60,"flashcardCount":38,"refCount":87,"topicCount":0,"scenarioCount":0,"file":"content/w19.js"}],"totals":{"worlds":20,"levels":125,"topics":284,"scenarios":643,"quiz":1234,"flashcards":1308,"refs":1071,"dialBoards":88,"diagrams":212,"defends":25,"labs":7}};
